state.data=loadData();
async function persist(){
  localStorage.setItem('proelium-data',JSON.stringify(state.data));
  if(location.protocol==='file:')return;
  if(state.syncing){toast('Aguarde a sincronização terminar e tente novamente.');return}
  state.syncing=true;
  try{
    const response=await fetch('./api/data',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:state.data,baseRevision:state.revision})});
    const payload=await response.json();
    if(response.status===409){await refreshSharedData(true);toast('Outro aparelho alterou os dados. A tela foi atualizada; repita sua última ação.');return}
    if(!response.ok)throw new Error(payload.error||'Falha ao salvar');
    state.revision=Number(payload.revision||state.revision||0);
    state.updatedAt=payload.updatedAt||state.updatedAt;
    state.lastSyncAt=new Date().toISOString();
    document.body.dataset.shared='true';
    updateSharedStatus();
  }catch{toast('Servidor indisponível: a alteração ainda não foi compartilhada.')}finally{state.syncing=false}
}
function normalizeSharedData(shared){const saved=shared||structuredClone(seed),resetCatalog=saved.catalogVersion!==seed.catalogVersion;const merged={...structuredClone(seed),...saved,catalogVersion:seed.catalogVersion,installations:saved.installations||[],activities:saved.activities||[],quotes:saved.quotes||[],opportunities:saved.opportunities||[],appointments:saved.appointments||[],products:resetCatalog?structuredClone(seed.products):(saved.products||[]),quoteRooms:resetCatalog?(saved.quoteRooms||[]).map(r=>({...r,items:[]})):(saved.quoteRooms||[])};merged.clients=(merged.clients||[]).map(c=>({...c,document:c.document||'',email:c.email||'',address:c.address||'',notes:c.notes||''}));merged.projects=(merged.projects||[]).map(p=>({...p,technicalStage:p.technicalStage||'Projeto técnico'}));return merged}
function normalizeSharedData(shared){const saved=shared||structuredClone(seed),resetCatalog=saved.catalogVersion!==seed.catalogVersion;const merged={...structuredClone(seed),...saved,catalogVersion:seed.catalogVersion,installations:saved.installations||[],activities:saved.activities||[],quotes:saved.quotes||[],opportunities:saved.opportunities||[],appointments:saved.appointments||[],projectChecklists:Array.isArray(saved.projectChecklists)?saved.projectChecklists:[],serviceReports:Array.isArray(saved.serviceReports)?saved.serviceReports:[],projectDeliveries:Array.isArray(saved.projectDeliveries)?saved.projectDeliveries:[],serviceOrders:Array.isArray(saved.serviceOrders)?saved.serviceOrders:[],supportTickets:Array.isArray(saved.supportTickets)?saved.supportTickets:[],equipmentHistory:Array.isArray(saved.equipmentHistory)?saved.equipmentHistory:[],financialEntries:Array.isArray(saved.financialEntries)?saved.financialEntries:[],evaluations:Array.isArray(saved.evaluations)?saved.evaluations:structuredClone(demoEvaluations),collaborators:saved.collaborators?.length?saved.collaborators:structuredClone(state.data.collaborators||[]),products:resetCatalog?structuredClone(seed.products):(saved.products||[]),quoteRooms:resetCatalog?(saved.quoteRooms||[]).map(r=>({...r,items:[]})):(saved.quoteRooms||[])};merged.clients=(merged.clients||[]).map(c=>({...c,document:c.document||'',email:c.email||'',address:c.address||'',notes:c.notes||''}));merged.projects=(merged.projects||[]).map(p=>({...p,technicalStage:p.technicalStage||'Projeto técnico'}));return ensureEmbraceCatalog(merged)}
async function refreshSharedData(force=false){
  const response=await fetch('./api/data',{cache:'no-store'});
  if(!response.ok)throw new Error('Servidor indisponível');
  const payload=await response.json();
  const remoteRevision=Number(payload.revision||0);
  const changedByRevision=remoteRevision>state.revision;
  const changedByDate=Boolean(payload.updatedAt&&payload.updatedAt!==state.updatedAt);
  if(payload.data&&(force||changedByRevision||changedByDate)){
    state.data=normalizeTeamNames(normalizeSharedData(payload.data));
    state.revision=remoteRevision;
    state.updatedAt=payload.updatedAt||null;
    localStorage.setItem('proelium-data',JSON.stringify(state.data));
    render();
  }else{
    state.revision=remoteRevision;
    state.updatedAt=payload.updatedAt||state.updatedAt;
  }
  state.lastSyncAt=new Date().toISOString();
  document.body.dataset.shared='true';
  updateSharedStatus();
  return payload;
}
async function connectSharedData(){
  if(location.protocol==='file:')return;
  try{
    const payload=await refreshSharedData(true);
    if(!payload.data||!payload.data.collaborators?.length||!payload.data.evaluations?.length||payload.data.collaborators.some(person=>person.name==='Hernani'||person.name==='Hernani Queiroz')||embraceCatalogSyncNeeded){await persist();embraceCatalogSyncNeeded=false}
    const events=new EventSource('./api/events');
    events.addEventListener('data-updated',async event=>{
      const update=JSON.parse(event.data);
      if(Number(update.revision)>state.revision&&!state.syncing){
        try{await refreshSharedData();toast('Dados atualizados por outro aparelho.')}catch{}
      }
    });
    events.onerror=()=>{document.body.dataset.shared='reconnecting';updateSharedStatus()};
    events.onopen=()=>{document.body.dataset.shared='true';updateSharedStatus()};
    setInterval(()=>refreshSharedData().catch(()=>{}),5000);
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshSharedData().catch(()=>{})});
  }catch{toast('Modo local: dados ainda não estão compartilhados.')}
}
function badge(value){const low=value.toLowerCase();const color=low.includes('bloq')||low.includes('atras')||low.includes('urg')?'red':low.includes('exec')||low.includes('andamento')||low.includes('instal')?'blue':low.includes('plane')||low.includes('alta')?'amber':'green';return `<span class="badge ${color}">${value}</span>`}
function matches(...values){return values.join(' ').toLowerCase().includes(state.query.toLowerCase())}

