    ...state.data.tasks.map(t=>({id:t.id,kind:'task',type:'Tarefa',title:t.title,detail:projectName(t.projectId),person:t.assignee,date:calendarDate(t.due),time:t.time||''})),
    ...state.data.installations.map(i=>({id:i.id,kind:'installation',type:'Instalação',title:i.type,detail:`${clientName(i.clientId)} · ${i.site}`,person:i.lead,date:calendarDate(i.due),time:''})),
    ...state.data.opportunities.filter(o=>!['Ganho','Perdido'].includes(o.stage)&&o.nextAction).map(o=>({id:o.id,kind:'opportunity',type:'Comercial',title:o.nextAction,detail:`${o.company} · ${o.stage}`,person:o.owner,date:calendarDate(o.nextDue),time:''}))
