function quality(){const records=state.data.evaluations||[],average=field=>records.length?(records.reduce((sum,r)=>sum+Number(r[field]||0),0)/records.length).toFixed(1):'—',stars=n=>n==='—'?'Sem avaliações':`${'★'.repeat(Math.round(n))}${'☆'.repeat(5-Math.round(n))}`;return heading('Qualidade e compromisso','Avaliações registradas pela equipe e pelo cliente, vinculadas ao projeto.','evaluation')+`<div class="quality-principles card"><div><b>1</b><strong>Relatório executado</strong><small>evidência de atividade, prazo e responsável</small></div><div><b>2</b><strong>Avaliação interna</strong><small>qualidade técnica e cumprimento do combinado</small></div><div><b>3</b><strong>Voz do cliente</strong><small>atendimento, entrega e satisfação percebida</small></div><div><b>4</b><strong>BI verificável</strong><small>indicadores para melhoria e reconhecimento</small></div></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Instalação</div><div class="kpi-value">${average('installation')}</div><div class="kpi-note rating">${stars(average('installation'))}</div></div><div class="kpi"><div class="kpi-top">Atendimento</div><div class="kpi-value">${average('service')}</div><div class="kpi-note rating">${stars(average('service'))}</div></div><div class="kpi"><div class="kpi-top">Compromisso</div><div class="kpi-value">${average('commitment')}</div><div class="kpi-note rating">${stars(average('commitment'))}</div></div><div class="kpi"><div class="kpi-top">Prazo</div><div class="kpi-value">${average('deadline')}</div><div class="kpi-note">${records.length} avaliações registradas</div></div></div><section class="card"><div class="card-head"><h3>Registros de avaliação</h3><span class="subtext">Escala de 1 a 5</span></div>${table(['Projeto','Fonte','Avaliador','Instalação','Atendimento','Compromisso','Prazo','Observação'],records.map(r=>`<tr><td><div class="entity">${projectName(r.projectId)}</div></td><td>${badge(r.source)}</td><td>${r.evaluator}</td><td>${r.installation}/5</td><td>${r.service}/5</td><td>${r.commitment}/5</td><td>${r.deadline}/5</td><td>${r.note||'—'}</td></tr>`))}</section>`}
function quality(){const records=state.data.evaluations||[],avg=(rows,key)=>rows.length?(rows.reduce((sum,r)=>sum+Number(r[key]||0),0)/rows.length):0,overall=r=>(Number(r.installation)+Number(r.service)+Number(r.commitment)+Number(r.deadline))/4,people=(state.data.collaborators||[]).map(person=>{const rows=records.filter(r=>(r.collaborator||r.evaluator)===person.name),score=avg(rows,'installation')+avg(rows,'service')+avg(rows,'commitment')+avg(rows,'deadline');return {...person,rows,score:rows.length?score/4:0}}).sort((a,b)=>b.score-a.score),internal=records.filter(r=>r.source==='Interna'),customer=records.filter(r=>r.source==='Cliente');return heading('Qualidade e compromisso','Desempenho rastreável da equipe, confirmado por execução, prazo e avaliação do cliente.','evaluation')+`<div class="quality-principles card"><div><b>1</b><strong>Relatório executado</strong><small>atividade, prazo e responsável</small></div><div><b>2</b><strong>Avaliação interna</strong><small>técnica, organização e compromisso</small></div><div><b>3</b><strong>Voz do cliente</strong><small>atendimento e entrega percebida</small></div><div><b>4</b><strong>Reconhecimento</strong><small>baseado em evidência verificável</small></div></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Qualidade técnica</div><div class="kpi-value">${avg(records,'installation').toFixed(1)}</div><div class="kpi-note">instalação</div></div><div class="kpi"><div class="kpi-top">Atendimento</div><div class="kpi-value">${avg(records,'service').toFixed(1)}</div><div class="kpi-note">percepção de serviço</div></div><div class="kpi"><div class="kpi-top">Compromisso</div><div class="kpi-value">${avg(records,'commitment').toFixed(1)}</div><div class="kpi-note">execução e postura</div></div><div class="kpi"><div class="kpi-top">Cliente</div><div class="kpi-value">${customer.length?avg(customer,'service').toFixed(1):'—'}</div><div class="kpi-note">${customer.length} avaliação(ões) externas</div></div></div><section class="team-performance card"><div class="card-head"><div><h3>Desempenho da equipe</h3><p class="subtext">Cenário demo: será substituído gradualmente por registros reais.</p></div><span class="subtext">escala 1 a 5</span></div><div class="team-performance-grid">${people.map((p,index)=>`<article><span class="team-rank">${String(index+1).padStart(2,'0')}</span><div class="collaborator-avatar">${p.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div><strong>${p.name}</strong><small>${p.role}</small></div><b>${p.score?p.score.toFixed(1):'—'}</b><div class="team-bars"><i title="Instalação" style="width:${p.rows.length?avg(p.rows,'installation')*20:0}%"></i><i title="Atendimento" style="width:${p.rows.length?avg(p.rows,'service')*20:0}%"></i><i title="Compromisso" style="width:${p.rows.length?avg(p.rows,'commitment')*20:0}%"></i><i title="Prazo" style="width:${p.rows.length?avg(p.rows,'deadline')*20:0}%"></i></div><em>${p.rows.length?`${p.rows.length} evidência(s)`: 'Aguardando avaliação'}</em></article>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Registros de avaliação</h3><span class="subtext">${internal.length} interna(s) · ${customer.length} do cliente</span></div>${table(['Projeto','Fonte','Pessoa avaliada','Avaliador','Instalação','Atendimento','Compromisso','Prazo'],records.map(r=>`<tr><td>${projectName(r.projectId)}</td><td>${badge(r.source)}</td><td><strong>${r.collaborator||r.evaluator}</strong></td><td>${r.evaluator}</td><td>${r.installation}/5</td><td>${r.service}/5</td><td>${r.commitment}/5</td><td>${r.deadline}/5</td></tr>`))}</section>`}
