function equipment(){const rows=state.data.equipment.filter(e=>matches(e.name,e.brand,e.model,e.serial,e.location)).map(e=>`<tr><td><div class="entity">${e.name}</div><div class="subtext">${e.brand||'Sem marca'}${e.model?` · ${e.model}`:''}</div></td><td>${e.serial||'Não informado'}</td><td>${e.location||'Não informado'}</td><td>${badge(e.status||'Ativo')}</td><td><button class="button secondary" data-edit-equipment="${e.id}">Editar</button></td></tr>`);const explanation=`<section class="card"><div class="card-head"><h3>Controle físico e rastreável</h3></div><p class="subtext">Use esta área para equipamentos que a Proelium possui, disponibiliza ou já instalou: patrimônio, estoque técnico, equipamentos em manutenção e ativos vinculados a um cliente. O catálogo de <b>Produtos e serviços</b> é diferente: ele reúne aquilo que pode entrar em um orçamento.</p></section>`;return heading('Equipamentos e ativos','Controle físico: estoque, instalação, garantia, manutenção e número de série.','equipment')+`<div class="module-toolbar"><button class="button secondary" data-add="equipment">+ Cadastrar equipamento físico</button><span class="subtext">Número de série é individual por unidade.</span></div>`+explanation+(rows.length?table(['Equipamento / modelo','Número de série','Local','Status',''],rows):'<div class="empty">Nenhum equipamento físico cadastrado. Clique em “Cadastrar equipamento físico” para registrar modelo, número de série, local e status.</div>')}
function knowledge(){const cards=state.data.articles.filter(a=>matches(a.title,a.tag,a.summary,a.basis)).map(a=>a.principles?`<article class="card article conduct-card"><span class="tag">${a.tag}</span><h3>${a.title}</h3><p>${a.summary}</p><ul>${a.principles.map(principle=>`<li>${principle}</li>`).join('')}</ul><small class="subtext"><b>Base:</b> ${a.basis||'Conteúdo interno a validar pela Proelium.'}</small></article>`:`<article class="card article"><span class="tag">${a.tag}</span><h3>${a.title}</h3><p>${a.summary}</p><small class="subtext"><b>Base:</b> ${a.basis||'Conteúdo interno a validar pela Proelium.'}</small><button class="button secondary">Abrir artigo</button></article>`).join('');const policy=`<section class="card"><div class="card-head"><h3>Critério de publicação</h3></div><p class="subtext">Esta base não promove marcas nem recomenda fornecedores. Cada conteúdo deve ter origem identificada: procedimento validado pela Proelium, registro documentado no N.E.M.O. ou referência técnica, científica ou normativa verificável. Conteúdos sem validação permanecem como rascunho interno.</p></section>`;const roadmap=`<section class="learning-roadmap" aria-label="Trilha de aprendizagem"><div><span>1</span><strong>Fundamentos</strong><small>Conceitos, riscos e vocabulário.</small></div><div><span>2</span><strong>Operacional</strong><small>Montagem, organização e checklist.</small></div><div><span>3</span><strong>Avançado</strong><small>Diagnóstico, calibração e comissionamento.</small></div><div><span>4</span><strong>Específico</strong><small>Atividade autorizada, projeto e responsável técnico.</small></div></section><p class="knowledge-warning"><b>Regra de segurança:</b> aprender aqui não autoriza intervenção elétrica, trabalho em altura ou qualquer atividade que exija habilitação, treinamento legal, análise de risco e responsável competente.</p>`;return heading('Base de conhecimento','Procedimentos, manuais e soluções reutilizáveis com origem identificada.')+policy+roadmap+`<div class="knowledge-grid">${cards||'<div class="empty">Nenhum artigo encontrado.</div>'}</div>`}
function biMarketElegante(){const all=state.data.projects.map(p=>{const margin=p.budget?Math.round((p.budget-p.cost)/p.budget*100):0,result=p.budget-p.cost,score=Math.max(0,Math.min(100,Math.round(margin*.6+p.progress*.4))),signal=score>=65?'Em destaque':score>=40?'Em atenção':'Prioridade';return {...p,margin,result,score,signal}}),filter=state.biMarketFilter,assets=all.filter(p=>filter==='all'||p.signal===filter).sort((a,b)=>state.biMarketSort==='result'?b.result-a.result:state.biMarketSort==='margin'?b.margin-a.margin:state.biMarketSort==='progress'?b.progress-a.progress:b.score-a.score),total=all.reduce((s,p)=>s+p.budget,0),result=all.reduce((s,p)=>s+p.result,0),average=all.length?Math.round(all.reduce((s,p)=>s+p.margin,0)/all.length):0,selected=assets.find(p=>p.id===state.biMarketAsset)||null;const projectCard=p=>`<button type="button" class="portfolio-project ${selected?.id===p.id?'selected':''}" data-market-asset="${p.id}"><span class="project-monogram">${(p.code||p.id.slice(-4)).toUpperCase()}</span><span class="project-copy"><strong>${p.name}</strong><small>${clientName(p.clientId)} · ${p.manager}</small></span><span class="project-stage"><i class="stage-dot ${p.signal==='Em destaque'?'good':p.signal==='Em atenção'?'watch':'priority'}"></i>${p.technicalStage}</span><span class="project-value"><small>Resultado projetado</small><b class="${p.result>=0?'up':'down'}">${p.result>=0?'+':''}${money(p.result)}</b></span><span class="project-progress"><small>${p.progress}% concluído</small><i><b style="width:${p.progress}%"></b></i></span></button>`;return heading('Desempenho de projetos','Uma leitura serena do portfólio: resultados, execução e decisões que merecem atenção.')+`<section class="portfolio-panel"><header class="portfolio-head"><div><small>VISÃO EXECUTIVA</small><h3>Portfólio EMS Studio</h3><p>Informações construídas pelos orçamentos, projetos, agenda e relatórios da operação.</p></div><span>Atualização pelos registros do app</span></header><div class="portfolio-summary"><div><small>Contratos e propostas</small><b>${money(total)}</b></div><div><small>Resultado projetado</small><b class="${result>=0?'up':'down'}">${money(result)}</b></div><div><small>Margem média</small><b>${average}%</b></div><div><small>Projetos em acompanhamento</small><b>${all.length}</b></div></div><div class="portfolio-controls"><div class="portfolio-filters">${[['all','Todos'],['Em destaque','Em destaque'],['Em atenção','Em atenção'],['Prioridade','Prioridade']].map(([id,label])=>`<button type="button" class="${filter===id?'active':''}" data-market-filter="${id}">${label}</button>`).join('')}</div><label>Organizar por <select id="marketSort"><option value="performance" ${state.biMarketSort==='performance'?'selected':''}>Visão geral</option><option value="result" ${state.biMarketSort==='result'?'selected':''}>Resultado</option><option value="margin" ${state.biMarketSort==='margin'?'selected':''}>Margem</option><option value="progress" ${state.biMarketSort==='progress'?'selected':''}>Andamento</option></select></label></div>${selected?portfolioDetail(selected):''}<section class="portfolio-list"><div class="portfolio-list-head"><strong>Projetos em acompanhamento</strong><small>${assets.length} projeto(s) nesta leitura</small></div>${assets.map(projectCard).join('')||'<div class="portfolio-empty">Nenhum projeto neste filtro.</div>'}</section></section>`}
function portfolioDetail(p){const cost=Math.max(0,p.cost),material=Math.round(cost*.62),labor=Math.round(cost*.26),logistics=Math.max(0,cost-material-labor),steps=[['Levantamento e escopo',p.progress>=15],['Cabeamento e infraestrutura',p.progress>=40],['Instalação e testes',p.progress>=70],['Entrega e acompanhamento',p.progress>=100]];return `<section class="project-brief"><header><div><small>CONSULTA DO PROJETO</small><h3>${p.name}</h3><p>${clientName(p.clientId)} · Responsável: ${p.manager}</p></div><button type="button" data-market-close aria-label="Fechar consulta">×</button></header><div class="project-brief-grid"><section class="brief-overview"><small>Situação atual</small><strong>${p.technicalStage}</strong><p>${p.progress}% do plano concluído</p><i><b style="width:${p.progress}%"></b></i><span>${p.signal}</span></section><section class="brief-finance"><small>Resumo financeiro</small><div><span>Valor aprovado</span><b>${money(p.budget)}</b></div><div><span>Custo previsto</span><b>${money(cost)}</b></div><div class="result"><span>Resultado projetado</span><b class="${p.result>=0?'up':'down'}">${money(p.result)}</b></div></section><section class="brief-costs"><small>Composição do custo</small><div><span>Materiais</span><i><b style="width:62%"></b></i><em>${money(material)}</em></div><div><span>Mão de obra</span><i><b style="width:26%"></b></i><em>${money(labor)}</em></div><div><span>Logística</span><i><b style="width:12%"></b></i><em>${money(logistics)}</em></div></section></div><section class="brief-journey"><div><strong>Caminho da execução</strong><small>Etapas concluídas e próximas decisões</small></div><ol>${steps.map(([label,done],i)=>`<li class="${done?'done':''}"><b>${done?'✓':i+1}</b><span>${label}</span></li>`).join('')}</ol></section><footer><span>Indicadores demonstrativos serão substituídos gradualmente por dados reais da operação.</span><strong>Margem estimada: ${p.margin}%</strong></footer></section>`}
const views={dashboard,clients,clientDetail,projects,processes,tasks,agenda,commercial,quoteDetail,products,installations,operations,finance,bi,biMarket:biMarketElegante,quality,collaborators,equipment,knowledge};

function render(){renderNav();$('#pageTitle').textContent=state.view==='clientDetail'?'Cliente 360°':state.view==='quoteDetail'?'Análise do orçamento':navItems.find(n=>n[0]===state.view)[2];$('#content').innerHTML=views[state.view]();if(state.view==='clientDetail')addDeleteControl();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.client));document.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>openQuote(b.dataset.quote));document.querySelectorAll('[data-quote-opportunity]').forEach(b=>b.onclick=()=>createQuoteFromOpportunity(b.dataset.quoteOpportunity));document.querySelectorAll('[data-approve-quote]').forEach(b=>b.onclick=()=>approveQuote(b.dataset.approveQuote));document.querySelectorAll('[data-edit-client]').forEach(b=>b.onclick=()=>openForm('client',b.dataset.editClient));document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>openForm('product',b.dataset.editProduct));document.querySelectorAll('[data-edit-equipment]').forEach(b=>b.onclick=()=>openForm('equipment',b.dataset.editEquipment));document.querySelectorAll('[data-toggle-product]').forEach(b=>b.onclick=()=>{const product=productById(b.dataset.toggleProduct);if(!product)return;product.active=product.active===false;product.status=product.active?'Ativo':'Descontinuado';persist();render();toast(product.active?'Produto ativado.':'Produto descontinuado.')});document.querySelectorAll('[data-delete-product]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.deleteProduct));document.querySelectorAll('[data-advance-opportunity]').forEach(b=>b.onclick=()=>advanceOpportunity(b.dataset.advanceOpportunity));document.querySelectorAll('[data-convert-opportunity]').forEach(b=>b.onclick=()=>convertOpportunity(b.dataset.convertOpportunity));document.querySelectorAll('[data-agenda-day]').forEach(day=>day.onclick=()=>openAgendaQuick(day.dataset.agendaDay));document.querySelectorAll('[data-add-appointment-date]').forEach(b=>b.onclick=()=>openForm('appointment','',{date:b.dataset.addAppointmentDate}));document.querySelectorAll('[data-agenda-month]').forEach(b=>b.onclick=()=>{state.agendaMonth+=b.dataset.agendaMonth==='next'?1:-1;if(state.agendaMonth>11){state.agendaMonth=0;state.agendaYear++}if(state.agendaMonth<0){state.agendaMonth=11;state.agendaYear--}state.agendaSelectedDate=null;render()});['productCategory','productBrand','productMode'].forEach(id=>{const control=$('#'+id);if(control)control.onchange=e=>{state[id]=e.target.value;render()}});const dim=$('#biDimension');if(dim)dim.onchange=e=>{state.biDimension=e.target.value;render()};document.querySelectorAll('[data-market-filter]').forEach(b=>b.onclick=()=>{state.biMarketFilter=b.dataset.marketFilter;render()});const marketSort=$('#marketSort');if(marketSort)marketSort.onchange=e=>{state.biMarketSort=e.target.value;render()};rememberUiState()}
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('#menuBackdrop').classList.toggle('visible',open)}
function go(view){state.view=view;state.query='';$('#globalSearch').value='';setMenu(false);render()}
function openClient(id){state.selectedClient=id;state.view='clientDetail';render()}
function openQuote(id){state.selectedQuote=id;state.view='quoteDetail';render()}
function addDeleteControl(){const actions=document.querySelector('.client-hero .hero-actions');if(!actions)return;const button=document.createElement('button');button.className='button danger-outline';button.textContent='Excluir cliente';button.onclick=()=>deleteClient(state.selectedClient);actions.prepend(button)}
function deleteClient(id){const client=state.data.clients.find(c=>c.id===id);if(!client)return;const projectIds=state.data.projects.filter(p=>p.clientId===id).map(p=>p.id),quoteIds=state.data.quotes.filter(q=>q.clientId===id).map(q=>q.id);if(!confirm(`Excluir ${client.name}?\n\nTambém serão removidos os projetos, tarefas, compromissos da agenda, orçamentos, instalações e todo o histórico vinculados.`))return;const before=structuredClone(state.data),byProject=item=>!projectIds.includes(item.projectId),byClientProject=item=>item.clientId!==id&&byProject(item);state.data.tasks=state.data.tasks.filter(byProject);state.data.appointments=state.data.appointments.filter(byClientProject);state.data.installations=state.data.installations.filter(byClientProject);state.data.activities=state.data.activities.filter(item=>item.clientId!==id);state.data.purchaseItems=(state.data.purchaseItems||[]).filter(byProject);state.data.serviceOrders=(state.data.serviceOrders||[]).filter(byClientProject);state.data.serviceReports=(state.data.serviceReports||[]).filter(byProject);state.data.projectChecklists=(state.data.projectChecklists||[]).filter(byProject);state.data.projectDeliveries=(state.data.projectDeliveries||[]).filter(byProject);state.data.supportTickets=(state.data.supportTickets||[]).filter(byClientProject);state.data.equipmentHistory=(state.data.equipmentHistory||[]).filter(byProject);state.data.financialEntries=(state.data.financialEntries||[]).filter(byClientProject);state.data.executionEntries=(state.data.executionEntries||[]).filter(byProject);state.data.evaluations=(state.data.evaluations||[]).filter(byProject);state.data.equipment=(state.data.equipment||[]).filter(byClientProject);state.data.procurementRequests=(state.data.procurementRequests||[]).filter(item=>!quoteIds.includes(item.quoteId));state.data.projects=state.data.projects.filter(p=>p.clientId!==id);state.data.quoteRooms=state.data.quoteRooms.filter(r=>!quoteIds.includes(r.quoteId));state.data.quotes=state.data.quotes.filter(q=>q.clientId!==id);state.data.clients=state.data.clients.filter(c=>c.id!==id);state.selectedClient=null;state.view='clients';persist();render();offerUndo(`Cliente ${client.name} e seus registros foram excluídos.`,before)}
function deleteProduct(id){const product=productById(id);if(!product)return;const uses=state.data.quoteRooms.reduce((n,r)=>n+r.items.filter(i=>i.productId===id).length,0);const detail=uses?`\n\nEste produto aparece em ${uses} ambiente(s) de orçamento e também será removido desses ambientes.`:'';if(!confirm(`Excluir ${product.name}?${detail}`))return;const before=structuredClone(state.data);state.data.products=state.data.products.filter(p=>p.id!==id);state.data.quoteRooms.forEach(r=>r.items=r.items.filter(i=>i.productId!==id));persist();render();offerUndo(`Produto ${product.name} foi excluído.`,before)}
function deleteAppointment(id){const appointment=state.data.appointments.find(a=>a.id===id);if(!appointment)return;if(!confirm(`Excluir o compromisso “${appointment.title}”?`))return;const before=structuredClone(state.data);state.data.appointments=state.data.appointments.filter(a=>a.id!==id);$('#agendaItemDialog').close();persist();render();offerUndo(`Compromisso ${appointment.title} foi excluído.`,before)}
function advanceOpportunity(id){const opportunity=state.data.opportunities.find(o=>o.id===id);if(!opportunity)return;const stages=['Novo contato','Qualificação','Visita','Orçamento'];const index=stages.indexOf(opportunity.stage);opportunity.stage=stages[Math.min(index+1,stages.length-1)];persist();render();toast(`Oportunidade movida para ${opportunity.stage}.`)}
function convertOpportunity(id){const opportunity=state.data.opportunities.find(o=>o.id===id);if(!opportunity)return;if(!['Orçamento','Ganho'].includes(opportunity.stage)){toast('Conclua o tratamento comercial até Orçamento antes de criar o cliente.');return}const existing=state.data.clients.find(c=>c.name.toLowerCase()===opportunity.company.toLowerCase());if(!existing){state.data.clients.push({id:uid('cli'),name:opportunity.company,document:'',contact:opportunity.contact,email:opportunity.email,phone:opportunity.phone,address:'',city:'',notes:`Origem: oportunidade comercial (${opportunity.source||'não informada'}).`,status:'Potencial'})}opportunity.stage='Ganho';opportunity.lossReason='';persist();render();toast(existing?'Oportunidade concluída como ganha.':'Cliente criado a partir da oportunidade comercial.')}
function createQuoteFromOpportunity(id){const opportunity=state.data.opportunities.find(o=>o.id===id);if(!opportunity)return;let quote=state.data.quotes.find(q=>q.opportunityId===id&&q.status!=='Aprovado');if(!quote){quote={id:uid('orc'),opportunityId:id,clientId:'',title:`Proposta — ${opportunity.company}`,value:0,status:'Em elaboração'};state.data.quotes.unshift(quote);opportunity.stage='Orçamento';persist()}state.selectedQuote=quote.id;state.view='quoteDetail';render();toast('Orçamento aberto. Adicione cômodos e itens para formar o valor.')}
function approveQuote(id){const quote=state.data.quotes.find(q=>q.id===id);if(!quote)return;const totals=state.data.quoteRooms.filter(room=>room.quoteId===id).reduce((all,room)=>{const total=roomTotals(room);all.cost+=total.cost;all.price+=total.price;return all},{cost:0,price:0});if(!totals.price){toast('Adicione ao menos um item com preço para aprovar este orçamento.');return}let client=quote.clientId?state.data.clients.find(c=>c.id===quote.clientId):null,opportunity=quote.opportunityId?state.data.opportunities.find(o=>o.id===quote.opportunityId):null;if(!client&&opportunity){client={id:uid('cli'),name:opportunity.company,document:'',contact:opportunity.contact,email:opportunity.email,phone:opportunity.phone,address:'',city:'',notes:`Origem: oportunidade comercial (${opportunity.source}).`,status:'Ativo'};state.data.clients.push(client)}if(!client){toast('Vincule um cliente ou uma oportunidade antes de aprovar.');return}quote.clientId=client.id;quote.value=totals.price;quote.status='Aprovado';if(opportunity){opportunity.stage='Ganho';opportunity.estimatedValue=totals.price;opportunity.lossReason=''}let project=state.data.projects.find(item=>item.quoteId===quote.id);if(!project){project={id:uid('prj'),quoteId:quote.id,code:`PRJ-${String(state.data.projects.length+1).padStart(3,'0')}`,name:quote.title.replace(/^Proposta — /,''),clientId:client.id,manager:opportunity?.owner||'A definir',technicalStage:'Projeto técnico',budget:totals.price,cost:totals.cost,status:'Planejamento',progress:0,due:'A definir'};state.data.projects.push(project)}else{project.budget=totals.price;project.cost=totals.cost}persist();render();toast('Orçamento aprovado: cliente e projeto criados com o valor calculado.')}

