function setupAccessibility(){applyAccessibility();$('#accessibilityButton').onclick=()=>$('#accessibilityDialog').showModal();$('#accessibilityClose').onclick=()=>$('#accessibilityDialog').close();$('#fontDown').onclick=()=>{const current=Number(localStorage.getItem('proelium-font-scale')||100),index=readingScales.indexOf(current);localStorage.setItem('proelium-font-scale',readingScales[Math.max(0,index-1)]);applyAccessibility()};$('#fontUp').onclick=()=>{const current=Number(localStorage.getItem('proelium-font-scale')||100),index=readingScales.indexOf(current);localStorage.setItem('proelium-font-scale',readingScales[Math.min(readingScales.length-1,index+1)]);applyAccessibility()};$('#backgroundPresence').oninput=e=>{localStorage.setItem('proelium-background-presence',e.target.value);applyAccessibility()};$('#privacyModeButton').onclick=()=>{localStorage.setItem('proelium-privacy-mode',String(localStorage.getItem('proelium-privacy-mode')!=='true'));applyAccessibility()};$('#seasonSelector').onchange=e=>{const choice=e.target.value;localStorage.setItem('proelium-season-choice',choice);applySeason(choice==='auto'?currentSeason():choice);toast(choice==='auto'?'Tema automático ativado.':`Tema ${e.target.options[e.target.selectedIndex].text} aplicado.`)};$('#themeRotation').onchange=e=>{localStorage.setItem('proelium-theme-rotation',e.target.value);setupThemeRotation();toast(Number(e.target.value)?'Tema rotativo ativado.':'Tema rotativo desligado.')};$('#contrastButton').onclick=()=>{localStorage.setItem('proelium-high-contrast',String(!document.body.classList.contains('high-contrast')));applyAccessibility()}}

