function openQuoteItemEdit(roomId,itemIndex){const room=state.data.quoteRooms.find(item=>item.id===roomId),item=room?.items[itemIndex],product=item&&productById(item.productId);if(!item||!product)return;$('#dialogTitle').textContent=`Ajustar ${product.name}`;$('#recordForm').dataset.kind='quoteItemEdit';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Salvar ajuste';$('#formFields').innerHTML=`<input type="hidden" name="roomId" value="${roomId}"><input type="hidden" name="itemIndex" value="${itemIndex}"><div class="field full"><label>Item</label><input value="${product.name}" disabled></div><div class="field"><label>Quantidade</label><input name="qty" type="number" min="1" step="1" value="${item.qty}" required></div><div class="field"><label>Desconto do item (%)</label><input name="discount" type="number" min="0" max="100" step="0.01" value="${item.discount||0}" required></div>`;$('#recordDialog').showModal()}
function duplicateQuote(id,reason){const source=state.data.quotes.find(quote=>quote.id===id);if(!source)return;const rootId=source.parentQuoteId||source.id,versions=state.data.quotes.filter(quote=>quote.id===rootId||quote.parentQuoteId===rootId),version=Math.max(...versions.map(quote=>Number(quote.version||1)))+1,copy={...structuredClone(source),id:uid('orc'),title:source.title.replace(/ · Rev\. \d+$/,'')+` · Rev. ${version}`,status:'Rascunho',version,parentQuoteId:rootId,revisedFromId:source.id,revisionReason:reason,createdAt:new Date().toISOString()};state.data.quotes.unshift(copy);const rooms=state.data.quoteRooms.filter(room=>room.quoteId===source.id);rooms.forEach(room=>state.data.quoteRooms.push({...structuredClone(room),id:uid('amb'),quoteId:copy.id}));state.selectedQuote=copy.id;persist();render();toast(`Revisão ${version} criada e registrada.`)}
function requestQuoteRevision(id){const quote=state.data.quotes.find(item=>item.id===id);if(!quote)return;const status=quoteStatus(quote);if(status==='Rascunho'){toast('Este orçamento ainda é rascunho. Ajuste-o diretamente, sem criar uma revisão.');return}if(status==='Aprovado'){toast('Este orçamento já foi aprovado. Para uma mudança comercial, abra uma nova proposta vinculada ao cliente.');return}$('#dialogTitle').textContent='Solicitar nova revisão';$('#recordForm').dataset.kind='quoteRevision';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Criar revisão registrada';$('#formFields').innerHTML=`<input type="hidden" name="quoteId" value="${quote.id}"><div class="field full"><label>Motivo da revisão</label><textarea name="reason" required placeholder="Ex.: cliente solicitou ajuste de escopo, desconto ou troca de equipamento."></textarea></div><p class="subtext">A proposta atual será preservada. A nova versão começará como Rascunho e terá o motivo registrado no histórico.</p>`;$('#recordDialog').showModal()}
function setQuoteStatus(id,status){const quote=state.data.quotes.find(item=>item.id===id);if(!quote||!quoteStatuses.includes(status))return;quote.status=status;persist();render();toast(`Orçamento marcado como ${status.toLowerCase()}.`)}
const block4ApproveQuote=approveQuote;approveQuote=id=>{const quote=state.data.quotes.find(item=>item.id===id);if(!quote)return;const totals=quoteTotals(id);if(!totals.price){toast('Adicione ao menos um item com preço para aprovar este orçamento.');return}let client=quote.clientId?state.data.clients.find(item=>item.id===quote.clientId):null,opportunity=quote.opportunityId?state.data.opportunities.find(item=>item.id===quote.opportunityId):null;if(!client&&opportunity){client={id:uid('cli'),name:opportunity.company,document:'',contact:opportunity.contact,email:opportunity.email,phone:opportunity.phone,address:'',city:'',notes:`Origem: oportunidade comercial (${opportunity.source}).`,status:'Ativo'};state.data.clients.push(client)}if(!client){toast('Vincule um cliente ou uma oportunidade antes de aprovar.');return}quote.clientId=client.id;quote.value=totals.price;quote.status='Aprovado';if(opportunity){opportunity.stage='Ganho';opportunity.estimatedValue=totals.price;opportunity.lossReason=''}let project=state.data.projects.find(item=>item.quoteId===quote.id);if(!project){project={id:uid('prj'),quoteId:quote.id,code:`PRJ-${String(state.data.projects.length+1).padStart(3,'0')}`,name:quote.title.replace(/^Proposta — /,''),clientId:client.id,manager:opportunity?.owner||'A definir',technicalStage:'Projeto técnico',budget:totals.price,cost:totals.cost,status:'Planejamento',progress:0,due:'A definir'};state.data.projects.push(project)}else{project.budget=totals.price;project.cost=totals.cost}persist();render();toast('Orçamento aprovado: cliente e projeto criados com valores líquidos.');};
function commercial(){const stages=['Novo contato','Qualificação','Visita','Orçamento'],active=state.data.opportunities.filter(opportunity=>!['Ganho','Perdido'].includes(opportunity.stage)),filtered=active.filter(opportunity=>matches(opportunity.company,opportunity.contact,opportunity.source,opportunity.owner,opportunity.stage)),won=state.data.opportunities.filter(opportunity=>opportunity.stage==='Ganho').length,lost=state.data.opportunities.filter(opportunity=>opportunity.stage==='Perdido').length,quoteRows=state.data.quotes.filter(quote=>matches(quote.title,quotePartyName(quote),quoteStatus(quote))).map(quote=>{const rooms=state.data.quoteRooms.filter(room=>room.quoteId===quote.id),total=quoteTotals(quote.id);return `<tr class="clickable-row" data-quote="${quote.id}"><td><div class="entity">${quote.title}</div><div class="subtext">${quote.id} · versão ${quote.version||1}</div></td><td>${quotePartyName(quote)}</td><td>${rooms.length}</td><td>${money(total.price||quote.value)}</td><td>${badge(quoteStatus(quote))}</td><td>→</td></tr>`});return heading('Comercial e contatos','Oportunidade → orçamento por ambientes → aprovação → cliente e projeto.','opportunity')+`<div class="module-toolbar"><button class="button secondary" data-add="quote">+ Orçamento para cliente</button></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Oportunidades abertas</div><div class="kpi-value">${active.length}</div><div class="kpi-note">em atendimento</div></div><div class="kpi"><div class="kpi-top">Próximas ações</div><div class="kpi-value">${active.filter(opportunity=>opportunity.nextAction).length}</div><div class="kpi-note">a acompanhar</div></div><div class="kpi"><div class="kpi-top">Ganhas</div><div class="kpi-value">${won}</div><div class="kpi-note">convertidas em cliente</div></div><div class="kpi"><div class="kpi-top">Perdidas</div><div class="kpi-value">${lost}</div><div class="kpi-note">com motivo registrado</div></div></div><div class="pipeline">${stages.map(stage=>{const deals=filtered.filter(opportunity=>opportunity.stage===stage);return `<section class="stage"><div class="stage-head"><span>${stage}</span><span class="stage-count">${deals.length}</span></div>${deals.map(opportunity=>`<article class="deal"><strong>${opportunity.company}</strong><p>${opportunity.contact} · ${opportunity.source}</p><p><b>Próxima:</b> ${opportunity.nextAction||'Não definida'}${opportunity.nextDue?` · ${opportunity.nextDue}`:''}</p><div class="deal-value">${opportunity.estimatedValue?money(opportunity.estimatedValue):'Valor a definir'}</div><div class="deal-actions"><button class="link-button" data-quote-opportunity="${opportunity.id}">Montar orçamento</button><button class="link-button" data-advance-opportunity="${opportunity.id}">Avançar</button><button class="link-button" data-convert-opportunity="${opportunity.id}">Converter em cliente</button></div></article>`).join('')||'<p class="subtext">Nenhuma oportunidade.</p>'}</section>`}).join('')}</div><section class="card commercial-history"><div class="card-head"><h3>Orçamentos por ambiente</h3></div>${table(['Orçamento','Contato / cliente','Ambientes','Valor líquido','Status',''],quoteRows)}</section>`}
function quoteDetail(){const quote=state.data.quotes.find(item=>item.id===state.selectedQuote);if(!quote){state.view='commercial';return commercial()}const rooms=state.data.quoteRooms.filter(room=>room.quoteId===quote.id),totals=quoteTotals(quote.id),margin=quoteMargin(totals),max=Math.max(1,...rooms.map(room=>quoteRoomTotals(room).price)),status=quoteStatus(quote),rootId=quote.parentQuoteId||quote.id,history=state.data.quotes.filter(item=>item.id===rootId||item.parentQuoteId===rootId).sort((a,b)=>Number(a.version||1)-Number(b.version||1));return `<button class="back-link" data-view="commercial">← Voltar para orçamentos</button>${heading(quote.title,`${quotePartyName(quote)} · ${quote.id} · versão ${quote.version||1} · ${status}`)}<div class="quote-actions"><button class="button secondary" data-add="room">+ Adicionar cômodo</button><button class="button primary" data-add="quoteItem">+ Adicionar item</button><button class="button secondary" data-add="packageToQuote">+ Inserir pacote</button><button class="button secondary" data-quote-revision="${quote.id}">Solicitar nova revisão</button>${status!=='Aprovado'?'<button class="button primary" data-approve-quote="'+quote.id+'">Aprovar → cliente e projeto</button>':''}</div><div class="module-toolbar quote-status-toolbar"><span class="subtext">Situação:</span>${quoteStatuses.map(item=>`<button class="button quote-status quote-status-${item.toLowerCase()} ${status===item?'active':''}" data-quote-set-status="${item}" data-quote-id="${quote.id}">${item}</button>`).join('')}</div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Ambientes</div><div class="kpi-value">${rooms.length}</div><div class="kpi-note">análise individual</div></div><div class="kpi"><div class="kpi-top">Venda bruta</div><div class="kpi-value">${money(totals.gross)}</div><div class="kpi-note">antes dos descontos</div></div><div class="kpi"><div class="kpi-top">Descontos</div><div class="kpi-value">${money(totals.discount)}</div><div class="kpi-note">itens e negociações</div></div><div class="kpi"><div class="kpi-top">Total líquido</div><div class="kpi-value">${money(totals.price)}</div><div class="kpi-note">proposta ao cliente</div></div><div class="kpi"><div class="kpi-top">Margem bruta</div><div class="kpi-value">${margin}%</div><div class="kpi-note">${money(totals.price-totals.cost)} projetados</div></div></div><div class="quote-analysis card"><div class="card-head"><h3>Comparação estratégica dos ambientes</h3><span class="subtext">receita líquida e margem por cômodo</span></div><div class="room-bars">${rooms.map(room=>{const values=quoteRoomTotals(room);return `<div class="room-bar"><strong>${room.name}</strong><div class="bi-track"><span style="width:${values.price/max*100}%"></span></div><span>${money(values.price)}</span><small>${quoteMargin(values)}% margem · ${money(values.discount)} desc.</small></div>`}).join('')}</div></div><section class="card commercial-history"><div class="card-head"><h3>Histórico de versões</h3><span class="subtext">${history.length} versão(ões)</span></div>${table(['Versão','Situação','Criada em','Motivo'],history.map(item=>`<tr><td><strong>v${item.version||1}</strong></td><td>${badge(quoteStatus(item))}</td><td>${item.createdAt?new Date(item.createdAt).toLocaleDateString('pt-BR'):'—'}</td><td>${item.revisionReason||'Versão inicial'}</td></tr>`))}</section><div class="room-grid">${rooms.map(room=>{const values=quoteRoomTotals(room);return `<section class="card room-card"><div class="card-head"><div><h3>${room.name}</h3><small>${room.items.length} itens · ${money(values.price)} líquido</small></div><strong>${quoteMargin(values)}% margem</strong></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qtd.</th><th>Desconto</th><th>Venda</th><th>Total</th><th></th></tr></thead><tbody>${room.items.map((item,index)=>{const product=productById(item.productId);return product?`<tr><td><div class="entity">${product.name}</div><div class="subtext">${product.mode}</div></td><td>${item.qty} ${product.unit}</td><td>${Number(item.discount||0)}%</td><td>${money(product.price)}</td><td>${money(product.price*item.qty*(1-Number(item.discount||0)/100))}</td><td><button class="link-button" data-edit-quote-item="${room.id}:${index}">Ajustar</button></td></tr>`:''}).join('')}</tbody></table></div><footer><span>Custo: ${money(values.cost)} · Desconto: ${money(values.discount)}</span><strong>Resultado: ${money(values.price-values.cost)}</strong></footer></section>`}).join('')||'<div class="empty">Adicione o primeiro cômodo para começar.</div>'}</div>`}
views.commercial=commercial;views.quoteDetail=quoteDetail;
document.addEventListener('click',event=>{const revision=event.target.closest('[data-quote-revision]'),status=event.target.closest('[data-quote-set-status]'),item=event.target.closest('[data-edit-quote-item]');if(revision)requestQuoteRevision(revision.dataset.quoteRevision);if(status)setQuoteStatus(status.dataset.quoteId,status.dataset.quoteSetStatus);if(item){const [roomId,index]=item.dataset.editQuoteItem.split(':');openQuoteItemEdit(roomId,Number(index))}});
const block4OpenCatalogSelect=openCatalogSelect;openCatalogSelect=(kind,prefill={})=>{if(kind==='packageToQuote'){const packages=(state.data.packages||[]).filter(item=>item.active!==false),rooms=state.data.quoteRooms.filter(item=>item.quoteId===state.selectedQuote);if(!packages.length){toast('Crie e preencha um pacote em Produtos e serviços antes de inseri-lo no orçamento.');return}if(!rooms.length){toast('Adicione ao menos um cômodo antes de inserir um pacote.');return}}block4OpenCatalogSelect(kind,prefill)};
render();

// Infraestrutura compartilhada: itens gerais começam distribuídos de forma igual por todos os ambientes.
function isSharedInfrastructure(product){return /roteador|router|gateway|modem|switch|rack|nobreak|patch\s*panel|cabo\s*(?:de\s*)?rede|cabeamento\s*(?:estruturado|de\s*rede)/i.test(`${product?.name||''} ${product?.model||''} ${product?.category||''}`)}
const sharedInfrastructureSearchOpen=openQuoteItemSearch;
openQuoteItemSearch=(prefill={})=>{
  sharedInfrastructureSearchOpen(prefill);
  const form=$('#recordForm');
  if(!form||form.dataset.kind!=='quoteItemSearch'||form.querySelector('[name="generalItem"]'))return;
  const roomField=form.elements.roomId;
  roomField?.closest('.field')?.insertAdjacentHTML('afterend',`<div class="field full shared-item-field"><label class="shared-item-toggle"><input type="checkbox" name="generalItem"><span><strong>Item geral do orçamento</strong><small>Distribui custo e venda igualmente por todos os ambientes. O local selecionado acima continua sendo o local físico do equipamento.</small></span></label><small class="subtext" data-general-item-hint>Use para infraestrutura central, como roteador, switch, rack, cabeamento principal ou nobreak.</small></div>`);
  const toggle=form.elements.generalItem,hint=form.querySelector('[data-general-item-hint]');
  form.addEventListener('click',event=>{
    const option=event.target.closest('[data-search-product]');
    if(!option)return;
    const product=productById(option.dataset.searchProduct),suggested=isSharedInfrastructure(product);
    toggle.checked=suggested;
    if(hint)hint.textContent=suggested?'Infraestrutura detectada: o rateio geral foi ativado. Você pode desligá-lo se este item atender apenas um ambiente.':'Ative quando o item atender a casa inteira; depois, use “Distribuir” para ajustar a participação de cada ambiente.';
  });
};
const sharedInfrastructureSave=saveRecord;
saveRecord=(kind,data,editId='')=>{
  if(kind==='quoteItemSearch'&&data.generalItem==='on'&&data.productId){
    const hostRoom=(state.data.quoteRooms||[]).find(room=>room.id===data.roomId),product=productById(data.productId),rooms=(state.data.quoteRooms||[]).filter(room=>room.quoteId===hostRoom?.quoteId),quantity=Number(data.qty||0),discount=Number(data.discount||0);
    if(!hostRoom||!product||!rooms.length||!Number.isFinite(quantity)||quantity<=0){toast('Confira o item, o ambiente físico e a quantidade antes de distribuir.');return false}
    const groupId=uid('geral'),part=Number((quantity/rooms.length).toFixed(4));
    rooms.forEach((room,index)=>room.items.push({productId:product.id,qty:index===rooms.length-1?Number((quantity-part*(rooms.length-1)).toFixed(4)):part,discount,capacityAllocation:{groupId,hostRoomId:hostRoom.id,capacityTotal:rooms.length,capacityUnit:'ambientes',amount:1,sourceProductQty:quantity,sharedInfrastructure:true}}));
    logAudit('Distribuiu item geral','Orçamento',`${product.name} · ${quantity} ${product.unit||'un'} · ${rooms.length} ambientes · local físico: ${hostRoom.name}`);
    persist();render();toast(`${product.name} foi distribuído igualmente pelos ${rooms.length} ambientes.`);return;
  }
  return sharedInfrastructureSave(kind,data,editId);
};
render();

// A distribuição engloba a movimentação: ajuste simples ou redistribuição de quantidade no mesmo lugar.
const streamlinedQuoteActionsView=views.quoteDetail;
views.quoteDetail=()=>streamlinedQuoteActionsView().replace(/\s*<button class="link-button" data-move-quote-item="[^"]+">Mover<\/button>/g,'');
const distributionAsMoveOpen=openCapacityDistribution;
openCapacityDistribution=(roomId,itemIndex)=>{
  distributionAsMoveOpen(roomId,itemIndex);
  const form=$('#recordForm');
  if(!form||form.dataset.kind!=='capacityDistribution')return;
  $('#dialogTitle').textContent='Distribuir ou mover item';
  const explanation=form.querySelector('.field.full .subtext');
  if(explanation)explanation.innerHTML='<strong>Distribuir entre ambientes</strong> · informe quanto deste item atende cada cômodo. A soma deve fechar a capacidade usada nesta obra; a sobra física não recebe custo no rateio.';
};
render();

// Também no Ajustar: a decisão de distribuir pode ser tomada depois que o item já entrou no orçamento.
const projectRateEditOpen=openQuoteItemEdit;
openQuoteItemEdit=(roomId,itemIndex)=>{
  projectRateEditOpen(roomId,itemIndex);
  const form=$('#recordForm'),room=(state.data.quoteRooms||[]).find(entry=>entry.id===roomId),item=room?.items?.[itemIndex],quantityField=form?.elements?.qty?.closest('.field');
  if(!form||form.dataset.kind!=='quoteItemEdit'||!item||!quantityField||form.querySelector('[name="generalItem"]'))return;
  const field=document.createElement('div');
  field.className='field shared-item-field shared-item-inline';
  field.innerHTML=`<label class="shared-item-toggle"><input type="checkbox" name="generalItem" ${item.capacityAllocation?.sharedInfrastructure?'checked':''}><span><strong>Ratear por todos os cômodos</strong><small>Distribui o valor deste item pelo projeto.</small></span></label>`;
  quantityField.insertAdjacentElement('afterend',field);
};
const projectRateEditSave=saveRecord;
saveRecord=(kind,data,editId='')=>{
  if(kind==='quoteItemEdit'&&data.generalItem==='on'){
    const room=(state.data.quoteRooms||[]).find(entry=>entry.id===data.roomId),item=room?.items?.[Number(data.itemIndex)],product=item&&productById(item.productId),rooms=(state.data.quoteRooms||[]).filter(entry=>entry.quoteId===room?.quoteId),quantity=Number(data.qty||0),discount=Number(data.discount||0);
    if(!room||!item||!product||!rooms.length||!Number.isFinite(quantity)||quantity<=0){toast('Confira a quantidade antes de distribuir este item.');return false}
    const oldGroup=item.capacityAllocation?.groupId;
    if(oldGroup)rooms.forEach(entry=>entry.items=entry.items.filter(candidate=>candidate.capacityAllocation?.groupId!==oldGroup));else room.items.splice(Number(data.itemIndex),1);
    const groupId=uid('geral'),part=Number((quantity/rooms.length).toFixed(4));
    rooms.forEach((entry,index)=>entry.items.push({productId:product.id,qty:index===rooms.length-1?Number((quantity-part*(rooms.length-1)).toFixed(4)):part,discount,capacityAllocation:{groupId,hostRoomId:room.id,capacityTotal:rooms.length,capacityUnit:'ambientes',amount:1,sourceProductQty:quantity,sharedInfrastructure:true}}));
    logAudit('Distribuiu item geral','Orçamento',`${product.name} ajustado para ${rooms.length} ambientes`);
    persist();render();toast(`${product.name} foi rateado por todos os cômodos.`);return;
  }
  return projectRateEditSave(kind,data,editId);
};
render();

// Conferência antes de confirmar: o rateio mostra o total, o já distribuído e o saldo em tempo real.
const capacityDistributionPreviewOpen=openCapacityDistribution;
openCapacityDistribution=(roomId,itemIndex)=>{
  capacityDistributionPreviewOpen(roomId,itemIndex);
  const form=$('#recordForm');
  if(!form||form.dataset.kind!=='capacityDistribution')return;
  const totalField=form.elements.capacityUsed;
  const physicalField=form.elements.capacityTotal;
  const unitField=form.elements.capacityUnit;
  const allocationFields=[...form.querySelectorAll('input[name^="capacity_"]')];
  const preview=document.createElement('section');
  preview.className='capacity-rateio-preview';
  preview.setAttribute('aria-live','polite');
  form.querySelector('#formFields')?.append(preview);
  const updatePreview=()=>{
    const total=Number(totalField?.value||0);
    const distributed=allocationFields.reduce((sum,field)=>sum+Number(field.value||0),0);
    const balance=Number((total-distributed).toFixed(4));
    const closed=Math.abs(balance)<.001;
    preview.classList.toggle('balanced',closed);
    preview.classList.toggle('unbalanced',!closed);
    preview.innerHTML=`<strong>Conferência do rateio comercial</strong><div><span>Usada na obra <b>${total||0} ${unitField?.value||'unidades'}</b></span><span>Distribuída <b>${distributed} ${unitField?.value||'unidades'}</b></span><span>${closed?'Rateio fechado':'Saldo a distribuir'} <b>${closed?'✓ 0':balance} ${unitField?.value||'unidades'}</b></span></div><small>${closed?`${physicalField?.value||total||0} ${unitField?.value||'unidades'} físicos · ${Math.max(0,Number(physicalField?.value||0)-total)} de sobra para o diagrama técnico.`:'A soma dos ambientes precisa fechar exatamente a capacidade usada nesta obra.'}</small>`;
  };
  [totalField,physicalField,unitField,...allocationFields].filter(Boolean).forEach(field=>field.addEventListener('input',updatePreview));
  updatePreview();
};
render();

// O total do visor precisa refletir exatamente os itens exibidos ao tocar em “Ganhas”.
const commercialMetricConsistencyView=views.commercial;views.commercial=()=>{const won=state.data.opportunities.filter(item=>item.stage==='Ganho').length,converted=state.data.opportunities.filter(item=>item.stage==='Ganho'&&state.data.clients.some(client=>client.name.toLowerCase()===item.company.toLowerCase())).length;return commercialMetricConsistencyView().replace(/(<div class="kpi-top">Ganhas<\/div><div class="kpi-value">)\d+(<\/div><div class="kpi-note">)[^<]+(<\/div>)/,`$1${won}$2${won} negócio(s) concluído(s) · ${converted} cliente(s) criado(s)$3`)};
render();

// Cadastro comercial: cliente e pessoa de contato são papéis diferentes; o responsável interno vem depois.
function openCommercialOpportunityManual(editId='',prefill={}){const current=editId?state.data.opportunities.find(item=>item.id===editId):null,value=(key,fallback='')=>prefill[key]??current?.[key]??fallback,actor=localStorage.getItem('proelium-current-actor')||'';$('#dialogTitle').textContent=current?'Editar oportunidade':'Novo registro comercial';$('#recordForm').dataset.kind='opportunity';$('#recordForm').dataset.editId=editId;$('#saveButton').textContent=current?'Salvar oportunidade':'Criar oportunidade';$('#formFields').innerHTML=`<div class="field full"><p class="subtext"><strong>Dados do cliente</strong> · informe o cliente ou a empresa. Quando houver os dois, use o formato <strong>Nome do cliente / Empresa</strong>.</p></div><div class="field full"><label>Cliente / empresa *</label><input name="company" autocomplete="organization" value="${value('company')}" placeholder="Ex.: Júlio César / Empresa Exemplo Ltda." required></div><div class="field"><label>Telefone do cliente *</label><input name="phone" type="tel" inputmode="tel" autocomplete="tel" value="${value('phone')}" placeholder="(11) 99999-9999" required></div><div class="field"><label>E-mail do cliente *</label><input name="email" type="email" inputmode="email" autocomplete="email" value="${value('email')}" placeholder="cliente@exemplo.com" required></div><div class="field full"><label>Pessoa de contato / responsável pelo cliente *</label><input name="contact" autocomplete="name" value="${value('contact')}" placeholder="Preencha manualmente o nome de quem responde pelo cliente" required><small class="subtext">Este é o segundo responsável: a pessoa autorizada a tratar do atendimento em nome do cliente ou empresa.</small></div><div class="field full"><p class="subtext"><strong>Condução comercial</strong> · define quem acompanha a oportunidade dentro da Proelium.</p></div><div class="field"><label>Responsável interno pelo atendimento *</label><select name="owner" required><option value="">Selecione</option>${(state.data.collaborators||[]).map(person=>`<option ${person.name===value('owner',actor)?'selected':''}>${person.name}</option>`).join('')}</select></div><div class="field"><label>Etapa atual</label><select name="stage">${['Novo contato','Qualificação','Visita','Orçamento'].map(stage=>`<option ${stage===value('stage','Novo contato')?'selected':''}>${stage}</option>`).join('')}</select></div><div class="field"><label>Origem do contato</label><select name="source"><option value="">Ainda não informado</option>${['Indicação','Instagram','Site','Telefone','Visita','Loja parceira','Outro'].map(source=>`<option ${source===value('source')?'selected':''}>${source}</option>`).join('')}</select></div><div class="field"><label>Próxima ação</label><input name="nextAction" value="${value('nextAction')}" placeholder="Ex.: agendar visita técnica"></div><div class="field"><label>Prazo da próxima ação</label><input name="nextDue" type="date" value="${value('nextDue')}"></div><div class="field"><label>Valor estimado (R$)</label><input name="estimatedValue" type="number" min="0" step="0.01" value="${value('estimatedValue',0)}"></div><div class="field"><label>Motivo de perda</label><input name="lossReason" value="${value('lossReason')}" placeholder="Preencher apenas se perdido"></div>`;$('#recordDialog').showModal()}
