// A importação do aparelho reduz digitação de telefone/e-mail, sem substituir o cliente nem a pessoa responsável.
function openCommercialOpportunityManualV2(editId='',prefill={}){const current=editId?state.data.opportunities.find(item=>item.id===editId):null,value=(key,fallback='')=>prefill[key]??current?.[key]??fallback,actor=localStorage.getItem('proelium-current-actor')||'';$('#dialogTitle').textContent=current?'Editar oportunidade':'Novo registro comercial';$('#recordForm').dataset.kind='opportunity';$('#recordForm').dataset.editId=editId;$('#saveButton').textContent=current?'Salvar oportunidade':'Criar oportunidade';$('#formFields').innerHTML=`<div class="field full"><p class="subtext"><strong>Dados do cliente</strong> · informe o nome do cliente. Se precisar registrar também a empresa, use <strong>Nome do cliente / Empresa</strong>; não use somente o nome da empresa.</p></div><div class="field full"><label>Cliente — ou Cliente / empresa *</label><input name="company" autocomplete="off" value="${value('company')}" placeholder="Ex.: Júlio César ou Júlio César / Empresa Exemplo Ltda." required></div><div class="field"><label>Telefone do cliente *</label><input name="phone" type="tel" inputmode="tel" autocomplete="tel" value="${value('phone')}" placeholder="(11) 99999-9999" required></div><div class="field"><label>E-mail do cliente *</label><input name="email" type="email" inputmode="email" autocomplete="email" value="${value('email')}" placeholder="cliente@exemplo.com" required></div><div class="field full"><button type="button" class="button secondary" id="importDeviceContact">Importar telefone e e-mail do aparelho</button><small class="subtext">A importação não altera o nome do cliente nem a pessoa de contato; esses campos permanecem manuais.</small></div><div class="field full"><label>Pessoa de contato / responsável pelo cliente *</label><input name="contact" autocomplete="off" value="${value('contact')}" placeholder="Preencha manualmente quem responde pelo cliente" required><small class="subtext">Pessoa autorizada a tratar do atendimento em nome do cliente ou empresa.</small></div><div class="field full"><p class="subtext"><strong>Condução comercial</strong> · define quem acompanha a oportunidade dentro da Proelium.</p></div><div class="field"><label>Responsável interno pelo atendimento *</label><select name="owner" required><option value="">Selecione</option>${(state.data.collaborators||[]).map(person=>`<option ${person.name===value('owner',actor)?'selected':''}>${person.name}</option>`).join('')}</select></div><div class="field"><label>Etapa atual</label><select name="stage">${['Novo contato','Qualificação','Visita','Orçamento'].map(stage=>`<option ${stage===value('stage','Novo contato')?'selected':''}>${stage}</option>`).join('')}</select></div><div class="field"><label>Origem do contato</label><select name="source"><option value="">Ainda não informado</option>${['Indicação','Instagram','Site','Telefone','Visita','Loja parceira','Outro'].map(source=>`<option ${source===value('source')?'selected':''}>${source}</option>`).join('')}</select></div><div class="field"><label>Próxima ação</label><input name="nextAction" value="${value('nextAction')}" placeholder="Ex.: agendar visita técnica"></div><div class="field"><label>Prazo da próxima ação</label><input name="nextDue" type="date" value="${value('nextDue')}"></div><div class="field"><label>Valor estimado (R$)</label><input name="estimatedValue" type="number" min="0" step="0.01" value="${value('estimatedValue',0)}"></div><div class="field"><label>Motivo de perda</label><input name="lossReason" value="${value('lossReason')}" placeholder="Preencher apenas se perdido"></div>`;$('#importDeviceContact').onclick=async()=>{if(!navigator.contacts?.select){toast('Importação de contatos não é suportada neste aparelho. Preencha telefone e e-mail manualmente.');return}try{const [deviceContact]=await navigator.contacts.select(['tel','email'],{multiple:false});if(!deviceContact)return;const fields=$('#recordForm').elements;let imported=0;if(deviceContact.tel?.[0]){fields.phone.value=deviceContact.tel[0];imported++}if(deviceContact.email?.[0]){fields.email.value=deviceContact.email[0];imported++}toast(imported?'Telefone e e-mail importados. Confira antes de salvar.':'O contato selecionado não possui telefone nem e-mail.')}catch(error){if(error.name!=='AbortError')toast('Não foi possível importar o contato.')}};$('#recordDialog').showModal()}
const manualCommercialV2OpenForm=openForm;openForm=(kind,editId='',prefill={})=>kind==='opportunity'?openCommercialOpportunityManualV2(editId,prefill):manualCommercialV2OpenForm(kind,editId,prefill);

// Auditoria e diagrama técnico: base rastreável para o futuro login e para a leitura de projetos.
if(!navItems.some(item=>item[0]==='diagram'))navItems.splice(navItems.findIndex(item=>item[0]==='purchases')+1,0,['diagram','⌘','Diagrama técnico']);
if(!navItems.some(item=>item[0]==='audit'))navItems.splice(navItems.findIndex(item=>item[0]==='diagram')+1,0,['audit','◷','Auditoria']);
const normalizeSharedWithAudit=normalizeSharedData;normalizeSharedData=shared=>{const data=normalizeSharedWithAudit(shared);data.auditLog=Array.isArray(shared?.auditLog)?shared.auditLog:[];return data};
if(!Array.isArray(state.data.auditLog))state.data.auditLog=[];
const auditActor=()=>localStorage.getItem('proelium-current-actor')||'Usuário do dispositivo';
function formatAuditDateTime(value){const date=value?new Date(value):null;return date&&!Number.isNaN(date.getTime())?date.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'medium'}):'Data e hora não informadas'}
function latestAuditEntry(){return[...(state.data.auditLog||[])].sort((left,right)=>new Date(right.at||0)-new Date(left.at||0))[0]||null}
function updateSharedStatus(){const title=$('#sharedStatusTitle'),detail=$('#sharedStatusDetail');if(!title||!detail)return;const sync=state.lastSyncAt?new Date(state.lastSyncAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):null,last=latestAuditEntry(),actor=last?.actor||'sem identificação',summary=last?`${last.area||'Área não informada'} · ${last.action||'Atualizou'}${last.detail?`: ${String(last.detail).slice(0,78)}${String(last.detail).length>78?'…':''}`:''}`:'Sem ação registrada';title.textContent=document.body.dataset.shared==='reconnecting'?'Servidor reconectando':'Servidor compartilhado';detail.textContent=sync?`Sincronizado às ${sync} · ${actor} · ${summary}`:'Sincronização automática ativa';detail.title=last?`Última ação registrada: ${formatAuditDateTime(last.at)} · ${actor} · ${last.action} em ${last.area} · ${last.detail||'sem detalhe'}`:'Aguardando a primeira sincronização'}
function logAudit(action,area,detail=''){state.data.auditLog.unshift({id:uid('audit'),at:new Date().toISOString(),actor:auditActor(),action,area,detail});state.data.auditLog=state.data.auditLog.slice(0,1000)}
function audit(){const records=state.data.auditLog||[],actor=auditActor(),last=latestAuditEntry(),rows=records.map(entry=>`<tr><td><strong>${formatAuditDateTime(entry.at)}</strong></td><td><strong>${entry.actor||'Não identificado'}</strong></td><td>${entry.action}</td><td>${entry.area}</td><td>${entry.detail||'—'}</td></tr>`);return heading('Auditoria','Histórico compartilhado de alterações. O usuário atual será substituído automaticamente pelo login quando a autenticação for implementada.')+`<section class="card"><div class="card-head"><div><h3>Identificação neste aparelho</h3><p class="subtext">Escolha quem está operando antes de criar, editar ou excluir registros.</p></div></div><div class="module-toolbar"><select id="auditActorSelect"><option ${actor==='Usuário do dispositivo'?'selected':''}>Usuário do dispositivo</option>${(state.data.collaborators||[]).map(person=>`<option ${person.name===actor?'selected':''}>${person.name}</option>`).join('')}</select><button class="button secondary" data-audit-actor>Usar este nome</button><span class="subtext">Atual: <strong>${actor}</strong></span></div></section><section class="card"><div class="card-head"><div><h3>Histórico de ações</h3><p class="subtext">${records.length} registro(s) mantidos no servidor compartilhado.${last?` Última ação: ${formatAuditDateTime(last.at)} por ${last.actor||'não identificado'}.`:''}</p></div></div>${records.length?table(['Data e hora','Quem','Ação','Área','Detalhe'],rows):'<div class="empty">Ainda não há ações registradas. Os próximos cadastros e ajustes aparecerão aqui.</div>'}</section>`}
function projectDiagramData(project){const quote=project?.quoteId&&state.data.quotes.find(item=>item.id===project.quoteId),quoteRooms=quote?(state.data.quoteRooms||[]).filter(room=>room.quoteId===quote.id):[],purchases=(state.data.purchaseItems||[]).filter(item=>item.projectId===project?.id),roomNames=[...new Set([...quoteRooms.map(room=>room.name),...purchases.map(item=>item.room).filter(Boolean)])];return roomNames.map(name=>{const room=quoteRooms.find(item=>item.name===name),items=(room?.items||[]).map(item=>{const product=productById(item.productId);return product?`${product.name} · ${item.qty} ${product.unit||'un'}`:'Item sem catálogo'});items.push(...purchases.filter(item=>item.room===name&&!item.productId).map(item=>`${item.name} · ${item.qty} ${item.unit||'un'}`));return {name,items}}).filter(room=>room.items.length)}
function diagram(){const selected=state.diagramProjectId||state.data.projects[0]?.id||'',project=state.data.projects.find(item=>item.id===selected),rooms=projectDiagramData(project),unassigned=(state.data.purchaseItems||[]).filter(item=>item.projectId===selected&&!rooms.some(room=>room.name===item.room));return heading('Diagrama técnico','Leitura automática inicial do orçamento e da lista de obra. Ele mostra a lógica de distribuição; conexões físicas e portas serão detalhadas com a leitura de planta.')+`<section class="card"><div class="module-toolbar"><label class="subtext">Projeto</label><select id="diagramProject">${state.data.projects.map(item=>`<option value="${item.id}" ${item.id===selected?'selected':''}>${item.code||'Projeto'} · ${item.name}</option>`).join('')}</select><span class="subtext">${project?.technicalStage||'Sem etapa'} · ${project?.status||'Sem situação'}</span></div></section>${project?`<section class="card"><div class="card-head"><div><h3>Fluxo lógico da obra</h3><p class="subtext">Visão gerada pelos ambientes e itens do orçamento. Não substitui projeto elétrico, rede ou documentação de fabricante.</p></div></div><div style="display:grid;gap:14px;max-width:960px;margin:auto"><div class="card" style="background:#173e53;color:white;text-align:center;padding:18px"><strong>Origem / rack técnico</strong><div style="font-size:.86em;opacity:.85;margin-top:5px">internet, alimentação, rede e centrais</div></div><div style="text-align:center;font-size:26px;color:#597987">↓</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px">${rooms.map(room=>`<div class="card" style="border:1px solid #b7cbd0;padding:16px"><strong>${room.name}</strong><div style="color:#597987;margin:8px 0">↓</div>${room.items.map(item=>`<div class="subtext" style="padding:7px 0;border-top:1px solid #e5eeee">${item}</div>`).join('')}</div>`).join('')||'<div class="empty">Este projeto ainda não possui itens de orçamento por ambiente. Adicione ambientes e itens ao orçamento ou use a lista de obra.</div>'}</div>${unassigned.length?`<div class="card"><strong>Itens sem ambiente definido</strong>${unassigned.map(item=>`<div class="subtext">${item.name} · ${item.qty} ${item.unit||'un'}</div>`).join('')}</div>`:''}</div></section>`:'<div class="empty">Crie ou selecione um projeto para gerar o diagrama.</div>'}`}
views.audit=audit;views.diagram=diagram;
const auditSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{const labels={client:'Cliente',opportunity:'Oportunidade',quote:'Orçamento',project:'Projeto',projectEdit:'Projeto',task:'Tarefa',appointment:'Compromisso',installation:'Instalação',product:'Produto ou serviço',room:'Cômodo',quoteItem:'Item de orçamento',quoteItemSearch:'Item de orçamento',purchaseItem:'Lista de obra',executionEntry:'Execução e mão de obra',agendaServiceReport:'Relatório de serviço',serviceReport:'Relatório de serviço',serviceOrderReport:'Relatório de serviço'};const result=auditSaveRecord(kind,data,editId);if(labels[kind]){logAudit(editId?'Editou':'Criou',labels[kind],data.name||data.title||data.company||data.description||data.execution||'Registro atualizado');persist();render()}return result};
