// Bloco 5 — execução operacional por projeto.
if(!Array.isArray(state.data.projectChecklists))state.data.projectChecklists=[];
if(!Array.isArray(state.data.serviceReports))state.data.serviceReports=[];
const projectFlowStages=['Projeto técnico','Cabeamento','Instalação','Testes','Entrega'];
const projectStageIndex=project=>Math.max(0,projectFlowStages.indexOf(project.technicalStage));
const checklistForProject=projectId=>(state.data.projectChecklists||[]).filter(item=>item.projectId===projectId);
const reportsForProject=projectId=>(state.data.serviceReports||[]).filter(item=>item.projectId===projectId).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
function openProjectStageUpdate(projectId){const project=state.data.projects.find(item=>item.id===projectId);if(!project)return;const options=projectFlowStages.map(stage=>`<option value="${stage}" ${stage===project.technicalStage?'selected':''}>${stage}</option>`).join('');$('#dialogTitle').textContent='Atualizar andamento do projeto';$('#recordForm').dataset.kind='projectStageUpdate';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Salvar andamento';$('#formFields').innerHTML=`<input type="hidden" name="projectId" value="${project.id}"><div class="field full"><label>Projeto</label><input value="${project.name}" disabled></div><div class="field"><label>Etapa atual</label><select name="technicalStage">${options}</select></div><div class="field"><label>Progresso (%)</label><input name="progress" type="number" min="0" max="100" step="1" value="${Number(project.progress||0)}" required></div><div class="field"><label>Situação</label><select name="status">${['Planejamento','Em execução','Bloqueado','Concluído'].map(status=>`<option value="${status}" ${status===project.status?'selected':''}>${status}</option>`).join('')}</select></div><div class="field"><label>Prazo</label><input name="due" type="text" value="${project.due||''}" placeholder="Ex.: 22 ago ou 2026-08-22"></div>`;$('#recordDialog').showModal()}
function openChecklistItem(projectId){const project=state.data.projects.find(item=>item.id===projectId);if(!project)return;$('#dialogTitle').textContent='Novo item de checklist';$('#recordForm').dataset.kind='projectChecklist';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Adicionar ao checklist';$('#formFields').innerHTML=`<input type="hidden" name="projectId" value="${project.id}"><div class="field full"><label>Projeto</label><input value="${project.name}" disabled></div><div class="field full"><label>Verificação</label><input name="title" required placeholder="Ex.: Identificar cabos e validar pontos instalados"></div><div class="field"><label>Fase</label><select name="phase">${projectFlowStages.map(stage=>`<option value="${stage}" ${stage===project.technicalStage?'selected':''}>${stage}</option>`).join('')}</select></div>`;$('#recordDialog').showModal()}
function openServiceReport(projectId){const project=state.data.projects.find(item=>item.id===projectId);if(!project)return;$('#dialogTitle').textContent='Registrar serviço executado';$('#recordForm').dataset.kind='serviceReport';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Salvar relatório';$('#formFields').innerHTML=`<input type="hidden" name="projectId" value="${project.id}"><div class="field full"><label>Projeto</label><input value="${project.name}" disabled></div><div class="field"><label>Data do serviço</label><input name="date" type="date" value="${todayInput()}" required></div><div class="field"><label>Responsável técnico</label><input name="technician" value="${project.manager||''}" required></div><div class="field full"><label>O que foi executado</label><textarea name="execution" required placeholder="Descreva atividades, testes realizados, materiais utilizados e pendências."></textarea></div><div class="field"><label>Situação do serviço</label><select name="status"><option>Concluído</option><option>Parcial</option><option>Pendente</option></select></div><div class="field"><label>Fotos / arquivos</label><input name="media" type="text" placeholder="Referência, link ou nome do arquivo"></div>`;$('#recordDialog').showModal()}
function projectDetail(){const project=state.data.projects.find(item=>item.id===state.selectedProject);if(!project){state.view='projects';return projects()}const stageIndex=projectStageIndex(project),tasks=state.data.tasks.filter(item=>item.projectId===project.id),checklist=checklistForProject(project.id),reports=reportsForProject(project.id),installation=state.data.installations.find(item=>item.projectId===project.id),done=checklist.filter(item=>item.done).length;return `<button class="back-link" data-project-back>← Voltar para projetos</button><div class="client-hero card"><div><p class="eyebrow">EXECUÇÃO DO PROJETO</p><h2>${project.name}</h2><p>${project.code} · ${clientName(project.clientId)} · ${badge(project.status||'Planejamento')}</p></div><div class="hero-actions"><button class="button secondary" data-project-stage="${project.id}">Atualizar andamento</button><button class="button primary" data-project-report="${project.id}">+ Relatório de serviço</button></div></div><div class="project-flow card">${projectFlowStages.map((stage,index)=>`<div class="${index<stageIndex?'done':index===stageIndex?'active':''}"><span>${index<stageIndex?'✓':index+1}</span><strong>${stage}</strong><small>${index<stageIndex?'concluída':index===stageIndex?'etapa atual':'aguardando'}</small></div>`).join('')}</div><div class="client-summary"><div class="card info-card"><span>Progresso</span><strong>${Number(project.progress||0)}%</strong><div class="progress wide"><span style="width:${Number(project.progress||0)}%"></span></div></div><div class="card info-card"><span>Responsável</span><strong>${project.manager||'A definir'}</strong><p>Prazo: ${project.due||'A definir'}</p></div><div class="card info-card"><span>Checklist</span><strong>${done}/${checklist.length}</strong><p>itens verificados</p></div><div class="card info-card"><span>Relatórios</span><strong>${reports.length}</strong><p>registros de campo</p></div></div><div class="project-execution-grid"><section class="card"><div class="card-head"><h3>Checklist da execução</h3><button data-project-checklist="${project.id}">+ Adicionar</button></div><div class="project-checklist">${checklist.map(item=>`<label class="check-row ${item.done?'completed':''}"><input type="checkbox" data-project-check="${item.id}" ${item.done?'checked':''}><span>${item.title}<small>${item.phase}</small></span></label>`).join('')||'<div class="empty">Adicione as verificações desta obra.</div>'}</div></section><section class="card"><div class="card-head"><h3>Tarefas e pendências</h3><button data-project-task="${project.id}">+ Tarefa</button></div><div class="project-task-list">${tasks.map(item=>`<article><div><strong>${item.title}</strong><small>${item.assignee||'Sem responsável'} · ${item.due||'Sem prazo'}</small></div>${badge(item.status||'Aberta')}</article>`).join('')||'<div class="empty">Nenhuma pendência registrada.</div>'}</div></section></div><section class="card service-report-list"><div class="card-head"><h3>Relatórios de serviço</h3><button data-project-report="${project.id}">+ Registrar serviço</button></div>${reports.map(report=>`<article><div><span class="agenda-type">${report.status}</span><strong>${report.date?new Date(report.date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem data'} · ${report.technician}</strong><p>${report.execution}</p>${report.media?`<small>Arquivo/foto: ${report.media}</small>`:''}</div></article>`).join('')||'<div class="empty">Registre a primeira visita ou serviço executado.</div>'}</section>${installation?`<section class="card project-linked-installation"><div class="card-head"><h3>Instalação vinculada</h3><button data-project-go="installations">Ver acompanhamento →</button></div><p>${installation.type} · ${installation.site} · ${installation.lead}</p></section>`:''}`}
function projects(){const list=state.data.projects.filter(project=>matches(project.name,project.code,clientName(project.clientId),project.manager,project.technicalStage));const rows=list.map(project=>`<tr><td><div class="entity">${project.name}</div><div class="subtext">${project.code}</div></td><td>${clientName(project.clientId)}</td><td>${badge(project.technicalStage||'Projeto técnico')}</td><td>${badge(project.status||'Planejamento')}</td><td>${project.manager||'A definir'}</td><td><strong>${project.progress||0}%</strong><div class="progress"><span style="width:${project.progress||0}%"></span></div></td><td><button class="button secondary" data-open-project="${project.id}">Abrir execução</button></td></tr>`);return heading('Projetos e execução','Acompanhe cada obra desde o planejamento até a entrega.','project')+`<div class="technical-flow compact card"><div><span>1</span><strong>Projeto técnico</strong></div><div><span>2</span><strong>Cabeamento</strong></div><div><span>3</span><strong>Instalação</strong></div><div><span>4</span><strong>Testes e entrega</strong></div></div>`+table(['Projeto','Cliente','Etapa','Situação','Responsável','Progresso',''],rows)}
