// Time operacional no BI: liderança e execução são lidas pela mesma base de evidências.
function performanceTeamPanel(){const records=state.data.evaluations||[],tasks=state.data.tasks||[],orders=state.data.serviceOrders||[],projects=state.data.projects||[],namesFor=person=>person.name==='Ernani Queiroz'?['Ernani Queiroz','Hernani Queiroz','Hernani']:[person.name],rows=(state.data.collaborators||[]).filter(person=>person.status!=='Inativo').map(person=>{const names=namesFor(person),evaluations=records.filter(record=>names.includes(record.collaborator)||names.includes(record.evaluator)),assignedTasks=tasks.filter(task=>names.includes(task.assignee)),assignedOrders=orders.filter(order=>names.includes(order.assignee)),managedProjects=projects.filter(project=>names.includes(project.manager)),quality=evaluations.length?evaluations.reduce((sum,record)=>sum+(Number(record.installation||0)+Number(record.service||0)+Number(record.commitment||0)+Number(record.deadline||0))/4,0)/evaluations.length:0,evidence=evaluations.length+assignedTasks.length+assignedOrders.length+managedProjects.length,score=evidence?Math.round(Math.min(100,quality*14+Math.min(30,evidence*5))):null;return {...person,evaluations,assignedTasks,assignedOrders,managedProjects,quality,evidence,score}}).sort((a,b)=>(b.score??-1)-(a.score??-1)||b.evidence-a.evidence),card=row=>`<article><span class="team-rank">${row.score===null?'—':row.score}</span><div class="collaborator-avatar">${row.name.split(' ').map(name=>name[0]).slice(0,2).join('')}</div><div><strong>${row.name}</strong><small>${row.role||'Colaborador'}</small></div><b>${row.quality?row.quality.toFixed(1):'—'}</b><div class="team-bars"><i title="Qualidade" style="width:${row.quality?row.quality*20:0}%"></i><i title="Tarefas" style="width:${Math.min(100,row.assignedTasks.length*25)}%"></i><i title="OS" style="width:${Math.min(100,row.assignedOrders.length*35)}%"></i><i title="Projetos" style="width:${Math.min(100,row.managedProjects.length*35)}%"></i></div><em>${row.evidence?`${row.evaluations.length} avaliação(ões) · ${row.assignedTasks.length} tarefa(s) · ${row.assignedOrders.length} OS · ${row.managedProjects.length} projeto(s)`:'Aguardando registros'}</em></article>`;return `<section class="team-performance card bi-performance-team"><div class="card-head"><div><h3>Time operacional e liderança</h3><p class="subtext">Inclui direção, gestão e operação. A pontuação combina avaliações e registros vinculados; sem evidência, não há nota inventada.</p></div><span class="subtext">nota de qualidade · índice de evidências</span></div><div class="team-performance-grid">${rows.map(card).join('')||'<p class="subtext">Cadastre colaboradores para acompanhar a equipe.</p>'}</div></section>`}
const biDesempenhoWithTeam=views.biMarket;
views.biMarket=()=>biDesempenhoWithTeam()+performanceTeamPanel();
render();

