// Relatório de campo: padrão enxuto para o técnico, com fotos que acompanham o histórico compartilhado.
function reportPhotoFields(){return `<div class="field full report-template-note"><strong>Fechamento do serviço</strong><small>Registre o que foi feito, o teste realizado, o que ficou pendente e a próxima ação. Isso forma o histórico técnico do cliente.</small></div><div class="field full"><label>Execução realizada</label><textarea name="execution" required placeholder="Ex.: passagem de cabos concluída, equipamentos fixados e rack identificado."></textarea></div><div class="field"><label>Testes e validações</label><textarea name="tests" placeholder="Ex.: rede validada, áudio testado, cliente orientado."></textarea></div><div class="field"><label>Pendências / próxima ação</label><textarea name="pending" placeholder="Ex.: retornar após chegada do equipamento."></textarea></div><div class="field full"><label>Fotos do serviço (até 3)</label><input id="serviceReportPhotos" type="file" accept="image/*" capture="environment" multiple><input id="serviceReportMedia" name="media" type="hidden" value=""><small class="subtext">As imagens são reduzidas antes de salvar para funcionarem também nos celulares.</small></div>`}
function openRichServiceReport(projectId,orderId=''){const project=state.data.projects.find(item=>item.id===projectId),order=orderId&&state.data.serviceOrders.find(item=>item.id===orderId);if(!project)return;$('#dialogTitle').textContent=order?`Relatório da ${order.code}`:'Registrar serviço executado';$('#recordForm').dataset.kind=order?'serviceOrderReport':'serviceReport';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Salvar relatório';$('#formFields').innerHTML=`${order?`<input type="hidden" name="serviceOrderId" value="${order.id}">`:''}<input type="hidden" name="projectId" value="${project.id}"><div class="field full"><label>Projeto</label><input value="${project.name}" disabled></div>${order?`<div class="field full"><label>OS vinculada</label><input value="${order.code} · ${order.type}" disabled></div>`:''}<div class="field"><label>Data do serviço</label><input name="date" type="date" value="${order?.date||todayInput()}" required></div><div class="field"><label>Responsável técnico</label><input name="technician" value="${order?.assignee||project.manager||''}" required></div><div class="field"><label>Situação</label><select name="status"><option>Concluído</option><option>Parcial</option><option>Pendente</option></select></div><div class="field"><label>Próxima revisão</label><input name="nextActionDate" type="date" value=""></div>${reportPhotoFields()}`;attachReportPhotos();$('#recordDialog').showModal()}
function compactServicePhoto(file){return new Promise(resolve=>{const reader=new FileReader();reader.onload=event=>{const image=new Image();image.onload=()=>{const limit=1280,scale=Math.min(1,limit/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.72))};image.onerror=()=>resolve(null);image.src=event.target.result};reader.onerror=()=>resolve(null);reader.readAsDataURL(file)})}
function attachReportPhotos(){const picker=$('#serviceReportPhotos'),target=$('#serviceReportMedia');picker?.addEventListener('change',async()=>{const files=[...picker.files].slice(0,3);$('#saveButton').disabled=true;const photos=(await Promise.all(files.map(compactServicePhoto))).filter(Boolean);target.value=JSON.stringify(photos);$('#saveButton').disabled=false;toast(photos.length?`${photos.length} foto(s) pronta(s) para o relatório.`:'Não foi possível preparar a foto.');})}
const richProjectReport=openServiceReport;openServiceReport=projectId=>openRichServiceReport(projectId);
const richOrderReport=openOrderServiceReport;openOrderServiceReport=orderId=>{const order=state.data.serviceOrders.find(item=>item.id===orderId);if(!order?.projectId){toast('Vincule esta OS a um projeto antes de registrar o relatório.');return}openRichServiceReport(order.projectId,orderId)};
