const quoteSearchSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='quoteItemSearch'){const room=state.data.quoteRooms.find(item=>item.id===data.roomId);if(!room)return;let productId=data.productId;if(!productId){const name=(data.requestName||'').trim();if(!name){toast('Escolha um produto ou informe o item que precisa de cotação.');return}const product={id:uid('prd'),sku:`COT-${Date.now().toString().slice(-5)}`,name,brand:data.requestBrand||'',model:'',category:data.requestCategory||'A cotar',supplier:'',mode:'Compra sob consulta',unit:'un',cost:0,price:0,status:'A cotar',active:true,pendingPurchase:true};state.data.products.push(product);if(!Array.isArray(state.data.procurementRequests))state.data.procurementRequests=[];state.data.procurementRequests.unshift({id:uid('cot'),productId:product.id,name:product.name,category:product.category,brand:product.brand,status:'A cotar',createdAt:new Date().toISOString(),quoteId:state.selectedQuote,roomId:room.id});productId=product.id}const existing=room.items.find(item=>item.productId===productId&&Number(item.discount||0)===Number(data.discount||0));if(existing)existing.qty+=Number(data.qty);else room.items.push({productId,qty:Number(data.qty),discount:Number(data.discount||0)});persist();render();toast(data.productId?'Item adicionado ao orçamento.':'Item a cotar criado e enviado para a fila de aquisição.');return}return quoteSearchSaveRecord(kind,data,editId)};
const procurementProductsView=views.products;views.products=()=>{const base=procurementProductsView(),requests=state.data.procurementRequests||[];return base+`<section class="card"><div class="card-head"><div><h3>Fila de cotação e aquisição</h3><p class="subtext">Itens inseridos no orçamento sem fornecedor ou preço definido.</p></div><span class="subtext">${requests.filter(item=>item.status==='A cotar').length} em cotação</span></div>${requests.length?table(['Item','Categoria','Origem','Situação'],requests.map(item=>`<tr><td><div class="entity">${item.name}</div><div class="subtext">${item.brand||'Marca a definir'}</div></td><td>${item.category}</td><td>Orçamento / ambiente</td><td>${badge(item.status||'A cotar')}</td></tr>`)):'<div class="empty">Nenhum item pendente de cotação.</div>'}</section>`};
