// Lista de obra e compras: transforma o orçamento aprovado em conferência operacional e aquisição.
if(!navItems.some(item=>item[0]==='purchases'))navItems.splice(navItems.findIndex(item=>item[0]==='finance'),0,['purchases','☷','Lista de obra e compras']);
const normalizeSharedWithPurchases=normalizeSharedData;normalizeSharedData=shared=>{const data=normalizeSharedWithPurchases(shared);data.purchaseItems=Array.isArray(shared?.purchaseItems)?shared.purchaseItems:[];return data};
if(!Array.isArray(state.data.purchaseItems))state.data.purchaseItems=[];
const purchaseSteps=['Planejado','A cotar','Comprado','Recebido','Conferido'];
function quoteMaterials(project){const quote=project.quoteId&&state.data.quotes.find(item=>item.id===project.quoteId);if(!quote)return [];return (state.data.quoteRooms||[]).filter(room=>room.quoteId===quote.id).flatMap(room=>(room.items||[]).map((item,index)=>({sourceKey:`${room.id}:${index}`,room:room.name,productId:item.productId,qty:Number(item.qty||0)})))}
function generatePurchaseList(projectId){const project=state.data.projects.find(item=>item.id===projectId);if(!project)return;const materials=quoteMaterials(project);if(!materials.length){toast('Este projeto ainda não possui itens de orçamento aprovados. Adicione o material manualmente.');return}let added=0;materials.forEach(material=>{if(state.data.purchaseItems.some(item=>item.projectId===projectId&&item.sourceKey===material.sourceKey))return;const product=productById(material.productId);if(!product)return;state.data.purchaseItems.push({id:uid('buy'),projectId,sourceKey:material.sourceKey,room:material.room,productId:product.id,name:product.name,qty:material.qty,unit:product.unit||'un',status:product.pendingPurchase?'A cotar':'Planejado',supplier:product.supplier||'',note:''});added++});persist();render();toast(added?`${added} item(ns) enviados para a lista de obra.`:'A lista deste projeto já foi gerada.')}
function openPurchaseItem(id=''){const item=id?state.data.purchaseItems.find(entry=>entry.id===id):null,value=(key,fallback='')=>item?.[key]??fallback;$('#dialogTitle').textContent=item?'Editar item da obra':'Adicionar item à lista de obra';$('#recordForm').dataset.kind='purchaseItem';$('#recordForm').dataset.editId=id;$('#saveButton').textContent=item?'Salvar item':'Adicionar à lista';$('#formFields').innerHTML=`<div class="field full"><label>Projeto</label><select name="projectId" required>${state.data.projects.map(project=>`<option value="${project.id}" ${project.id===value('projectId')?'selected':''}>${project.code||'Projeto'} · ${project.name}</option>`).join('')}</select></div><div class="field"><label>Item / material</label><input name="name" value="${value('name')}" placeholder="Ex.: cabo, suporte, equipamento ou insumo" required></div><div class="field"><label>Ambiente / frente</label><input name="room" value="${value('room')}" placeholder="Ex.: Sala, rack, cabeamento"></div><div class="field"><label>Quantidade</label><input name="qty" type="number" min="0.01" step="0.01" value="${value('qty',1)}" required></div><div class="field"><label>Unidade</label><select name="unit">${['un','m','kit','cx','h'].map(unit=>`<option ${unit===value('unit','un')?'selected':''}>${unit}</option>`).join('')}</select></div><div class="field"><label>Situação</label><select name="status">${purchaseSteps.map(step=>`<option ${step===value('status','Planejado')?'selected':''}>${step}</option>`).join('')}</select></div><div class="field"><label>Fornecedor</label><input name="supplier" value="${value('supplier')}" placeholder="Opcional"></div><div class="field full"><label>Conferência / observação</label><textarea name="note" placeholder="Modelo, medida, prazo, quantidade conferida ou pendência.">${value('note')}</textarea></div>`;$('#recordDialog').showModal()}
function purchases(){const items=state.data.purchaseItems||[],open=items.filter(item=>!['Conferido'].includes(item.status)),rows=items.map(item=>{const project=state.data.projects.find(entry=>entry.id===item.projectId);return `<tr><td><div class="entity">${item.name}</div><div class="subtext">${item.room||'Frente não informada'} · ${item.note||'Sem observação'}</div></td><td>${project?.name||'Projeto removido'}</td><td>${item.qty} ${item.unit||'un'}</td><td>${item.supplier||'A definir'}</td><td>${badge(item.status||'Planejado')}</td><td><button class="button secondary" data-purchase-advance="${item.id}">Avançar</button> <button class="button secondary" data-purchase-edit="${item.id}">Editar</button> <button class="delete-icon" aria-label="Excluir item" title="Excluir item" data-purchase-delete="${item.id}">×</button></td></tr>`});const eligibleProjects=state.data.projects.filter(project=>quoteMaterials(project).length);return heading('Lista de obra e compras','Conferência de material por projeto: do orçamento à compra, recebimento e validação no campo.')+`<div class="module-toolbar"><button class="button primary" data-purchase-add>+ Adicionar item</button><span class="subtext">Gere a lista a partir de um orçamento aprovado ou inclua materiais de campo manualmente.</span></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Itens na lista</div><div class="kpi-value">${items.length}</div><div class="kpi-note">material e equipamentos</div></div><div class="kpi"><div class="kpi-top">Pendentes</div><div class="kpi-value">${open.length}</div><div class="kpi-note">a cotar, comprar ou conferir</div></div><div class="kpi"><div class="kpi-top">Conferidos</div><div class="kpi-value">${items.filter(item=>item.status==='Conferido').length}</div><div class="kpi-note">prontos para a obra</div></div></div><section class="card"><div class="card-head"><div><h3>Gerar a partir de orçamento aprovado</h3><p class="subtext">Cria uma lista persistente para cada projeto que possui orçamento vinculado.</p></div></div><div class="module-toolbar">${eligibleProjects.map(project=>`<button class="button secondary" data-purchase-generate="${project.id}">${project.code||'Projeto'} · Gerar lista</button>`).join('')||'<span class="subtext">Nenhum projeto com orçamento aprovado vinculado.</span>'}</div></section><section class="card"><div class="card-head"><h3>Conferência e aquisição</h3><span class="subtext">Planejado → cotar → comprado → recebido → conferido</span></div>${items.length?table(['Material / observação','Projeto','Qtd.','Fornecedor','Situação',''],rows):'<div class="empty">Nenhum item na lista. Gere pelo orçamento ou adicione o primeiro material.</div>'}</section>`}
views.purchases=purchases;
const purchaseSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='purchaseItem'){const record={id:editId||uid('buy'),projectId:data.projectId,name:data.name,room:data.room||'',qty:Number(data.qty||0),unit:data.unit||'un',status:data.status||'Planejado',supplier:data.supplier||'',note:data.note||''};const index=state.data.purchaseItems.findIndex(item=>item.id===editId);if(index>=0)state.data.purchaseItems[index]={...state.data.purchaseItems[index],...record};else state.data.purchaseItems.unshift(record);persist();render();toast(editId?'Item da obra atualizado.':'Item adicionado à lista de obra.');return}return purchaseSaveRecord(kind,data,editId)};
const purchaseRender=render;render=()=>{purchaseRender();document.querySelectorAll('[data-purchase-add]').forEach(button=>button.onclick=()=>openPurchaseItem());document.querySelectorAll('[data-purchase-edit]').forEach(button=>button.onclick=()=>openPurchaseItem(button.dataset.purchaseEdit));document.querySelectorAll('[data-purchase-generate]').forEach(button=>button.onclick=()=>generatePurchaseList(button.dataset.purchaseGenerate));document.querySelectorAll('[data-purchase-advance]').forEach(button=>button.onclick=()=>{const item=state.data.purchaseItems.find(entry=>entry.id===button.dataset.purchaseAdvance);if(!item)return;item.status=purchaseSteps[Math.min(purchaseSteps.length-1,purchaseSteps.indexOf(item.status)+1)];persist();render();toast(`Item atualizado para ${item.status}.`)});document.querySelectorAll('[data-purchase-delete]').forEach(button=>button.onclick=()=>{const item=state.data.purchaseItems.find(entry=>entry.id===button.dataset.purchaseDelete);if(!item||!confirm(`Excluir “${item.name}” da lista de obra?`))return;const before=structuredClone(state.data);state.data.purchaseItems=state.data.purchaseItems.filter(entry=>entry.id!==item.id);persist();render();offerUndo(`Item ${item.name} removido da lista de obra.`,before)})};
render();

