function openQuoteItemMove(roomId,itemIndex){const sourceRoom=(state.data.quoteRooms||[]).find(room=>room.id===roomId),item=sourceRoom?.items?.[itemIndex],product=item&&productById(item.productId),destinations=(state.data.quoteRooms||[]).filter(room=>room.quoteId===sourceRoom?.quoteId&&room.id!==roomId);if(!sourceRoom||!item||!product)return;if(!destinations.length){toast('Crie outro cômodo neste orçamento antes de mover o item.');return}$('#dialogTitle').textContent='Mover item de orçamento';$('#recordForm').dataset.kind='quoteItemMove';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Mover item';$('#formFields').innerHTML=`<input type="hidden" name="sourceRoomId" value="${roomId}"><input type="hidden" name="itemIndex" value="${itemIndex}"><div class="field full"><label>Item</label><input data-move-available value="${product.name} · ${item.qty} ${product.unit} disponíveis" disabled></div><div class="field"><label>Cômodo atual</label><input value="${sourceRoom.name}" disabled></div><div class="field"><label>Quantidade a mover *</label><input name="quantity" type="number" min="0.01" max="${item.qty}" step="0.01" value="${Math.min(1,Number(item.qty))}" required></div><div class="field"><label>Destino *</label><select name="targetRoomId" required>${destinations.map(room=>`<option value="${room.id}">${room.name}</option>`).join('')}</select></div><p class="subtext">O restante continuará no cômodo atual. O desconto será preservado; se o mesmo item já existir no destino com o mesmo desconto, as quantidades serão somadas.</p>`;$('#recordDialog').showModal()}
const quoteItemMoveView=views.quoteDetail;views.quoteDetail=()=>quoteItemMoveView().replace(/(<button class="link-button" data-edit-quote-item="([^":]+):(\d+)">Ajustar<\/button>)/g,(match,button,roomId,index)=>`${button} <button class="link-button" data-move-quote-item="${roomId}:${index}">Mover</button>`);
const quoteItemMoveSave=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='quoteItemMove'){const sourceRoom=(state.data.quoteRooms||[]).find(room=>room.id===data.sourceRoomId),targetRoom=(state.data.quoteRooms||[]).find(room=>room.id===data.targetRoomId),index=Number(data.itemIndex),item=sourceRoom?.items?.[index],product=item&&productById(item.productId),quantity=Number(data.quantity);if(!sourceRoom||!targetRoom||!item||!product||sourceRoom.quoteId!==targetRoom.quoteId){toast('Não foi possível localizar os cômodos deste orçamento.');return}if(!Number.isFinite(quantity)||quantity<=0||quantity>Number(item.qty)){toast('Informe uma quantidade válida, dentro do disponível no cômodo atual.');return}const existing=targetRoom.items.find(targetItem=>targetItem.productId===item.productId&&Number(targetItem.discount||0)===Number(item.discount||0));if(existing)existing.qty+=quantity;else targetRoom.items.push({...structuredClone(item),qty:quantity});const remaining=Number((Number(item.qty)-quantity).toFixed(4));if(remaining<=0)sourceRoom.items.splice(index,1);else item.qty=remaining;logAudit('Moveu','Orçamento',`${product.name}: ${quantity} ${product.unit} · ${sourceRoom.name} → ${targetRoom.name}`);persist();if(remaining>0){const form=$('#recordForm'),quantityInput=form.elements.quantity,available=form.querySelector('[data-move-available]');quantityInput.max=String(remaining);quantityInput.value=String(Math.min(1,remaining));if(available)available.value=`${product.name} · ${remaining} ${product.unit} disponíveis`;toast(`${quantity} ${product.unit} movido(s). Restam ${remaining} no ${sourceRoom.name}.`);return false}render();toast(`${quantity} ${product.unit} de ${product.name} movido(s) para ${targetRoom.name}.`);return}return quoteItemMoveSave(kind,data,editId)};
