function openCapacityDistribution(roomId,itemIndex){const room=(state.data.quoteRooms||[]).find(entry=>entry.id===roomId),item=room?.items?.[itemIndex],product=item&&productById(item.productId),rooms=(state.data.quoteRooms||[]).filter(entry=>entry.quoteId===room?.quoteId);if(!room||!item||!product)return;const current=item.capacityAllocation,groupId=current?.groupId||uid('rateio'),entries=current?capacityGroups(room.quoteId).find(group=>group.groupId===current.groupId)?.allocations||[]:[],amountFor=id=>entries.find(entry=>entry.roomId===id)?.amount??(id===roomId?capacityDefault(product,item.qty):0),sourceQty=Number(current?.sourceProductQty??item.qty),physicalTotal=Number(current?.capacityTotal??capacityDefault(product,item.qty)),usedTotal=current?Number(current.capacityUsed??entries.reduce((sum,entry)=>sum+Number(entry.amount||0),0)):physicalTotal,unit=current?.capacityUnit||'circuitos',hostRoomId=current?.hostRoomId||roomId;$('#dialogTitle').textContent=current?'Ajustar distribuição de capacidade':'Distribuir capacidade';$('#recordForm').dataset.kind='capacityDistribution';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Salvar rateio';$('#formFields').innerHTML=`<input type="hidden" name="sourceRoomId" value="${roomId}"><input type="hidden" name="itemIndex" value="${itemIndex}"><input type="hidden" name="groupId" value="${groupId}"><input type="hidden" name="productId" value="${product.id}"><input type="hidden" name="discount" value="${Number(item.discount||0)}"><input type="hidden" name="sourceQty" value="${sourceQty}"><div class="field full"><label>Equipamento compartilhado</label><input value="${product.name} · ${sourceQty} ${product.unit}" disabled><small class="subtext">O equipamento continua instalado em um local físico, mas custo e venda serão distribuídos somente pela capacidade usada nesta obra.</small></div><div class="field"><label>Local físico do equipamento</label><select name="hostRoomId">${rooms.map(entry=>`<option value="${entry.id}" ${entry.id===hostRoomId?'selected':''}>${entry.name}</option>`).join('')}</select></div><div class="field"><label>Capacidade física total *</label><input name="capacityTotal" type="number" min="0.01" step="0.01" value="${physicalTotal}" required></div><div class="field"><label>Capacidade usada nesta obra *</label><input name="capacityUsed" type="number" min="0.01" max="${physicalTotal}" step="0.01" value="${usedTotal}" required></div><div class="field full"><label>Unidade de capacidade</label><input name="capacityUnit" value="${unit}" placeholder="Ex.: portas, circuitos, zonas ou canais" required></div><div class="field full"><p class="subtext"><strong>Distribuição comercial por ambiente</strong> · a soma precisa fechar a capacidade usada nesta obra. A sobra física fica registrada para o diagrama técnico, sem receber custo no rateio.</p></div>${rooms.map(entry=>`<div class="field"><label>${entry.name}</label><input name="capacity_${entry.id}" type="number" min="0" step="0.01" value="${amountFor(entry.id)}"></div>`).join('')}`;$('#recordDialog').showModal()}
const capacityDistributionSave=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind!=='capacityDistribution')return capacityDistributionSave(kind,data,editId);const sourceRoom=(state.data.quoteRooms||[]).find(room=>room.id===data.sourceRoomId),sourceItem=sourceRoom?.items?.[Number(data.itemIndex)],product=productById(data.productId),physicalTotal=Number(data.capacityTotal),capacityUsed=Number(data.capacityUsed),quoteId=sourceRoom?.quoteId;if(!sourceRoom||!sourceItem||!product||!Number.isFinite(physicalTotal)||physicalTotal<=0||!Number.isFinite(capacityUsed)||capacityUsed<=0||capacityUsed>physicalTotal){toast('Informe a capacidade física e a capacidade usada nesta obra corretamente.');return false}const allocations=(state.data.quoteRooms||[]).filter(room=>room.quoteId===quoteId).map(room=>({roomId:room.id,amount:Number(data[`capacity_${room.id}`]||0)})).filter(entry=>Number.isFinite(entry.amount)&&entry.amount>0),used=allocations.reduce((sum,entry)=>sum+entry.amount,0);if(Math.abs(used-capacityUsed)>.001){toast(`A distribuição soma ${used}; ela precisa fechar ${capacityUsed} ${data.capacityUnit} usados nesta obra.`);return false}const groupId=data.groupId;(state.data.quoteRooms||[]).filter(room=>room.quoteId===quoteId).forEach(room=>{room.items=room.items.filter(entry=>entry.capacityAllocation?.groupId!==groupId)});if(!sourceItem.capacityAllocation){const index=sourceRoom.items.indexOf(sourceItem);if(index>=0)sourceRoom.items.splice(index,1)}const sourceQty=Number(data.sourceQty),discount=Number(data.discount||0);allocations.forEach(entry=>{const target=(state.data.quoteRooms||[]).find(room=>room.id===entry.roomId);target?.items.push({productId:product.id,qty:Number((sourceQty*entry.amount/capacityUsed).toFixed(4)),discount,capacityAllocation:{groupId,hostRoomId:data.hostRoomId,capacityTotal:physicalTotal,capacityUsed,capacityUnit:String(data.capacityUnit).trim(),amount:entry.amount,sourceProductQty:sourceQty}})});const host=(state.data.quoteRooms||[]).find(room=>room.id===data.hostRoomId);logAudit('Distribuiu capacidade','Orçamento',`${product.name} · ${capacityUsed}/${physicalTotal} ${data.capacityUnit} usadas · instalado em ${host?.name||'local não informado'}`);persist();render();toast(`Rateio salvo: ${capacityUsed} de ${physicalTotal} ${data.capacityUnit} distribuídas entre ${allocations.length} ambiente(s).`);return};
const capacityMoveGuard=openQuoteItemMove;openQuoteItemMove=(roomId,itemIndex)=>{const item=(state.data.quoteRooms||[]).find(room=>room.id===roomId)?.items?.[itemIndex];if(item?.capacityAllocation){toast('Este item faz parte de um rateio técnico. Use “Distribuir capacidade” para alterar os ambientes.');return}return capacityMoveGuard(roomId,itemIndex)};
const capacityDistributionView=views.quoteDetail;views.quoteDetail=()=>{const quote=state.data.quotes.find(item=>item.id===state.selectedQuote),groups=quote?capacityGroups(quote.id):[],summary=groups.length?`<section class="card capacity-summary"><div class="card-head"><div><h3>Rateios técnicos</h3><p class="subtext">Equipamentos centrais distribuídos pelos ambientes atendidos, sem duplicar custo ou venda.</p></div></div><div class="capacity-summary-list">${groups.map(group=>{const product=productById(group.productId),host=(state.data.quoteRooms||[]).find(room=>room.id===group.hostRoomId),used=Number(group.capacityUsed??group.capacityTotal);return `<article><strong>${product?.name||'Equipamento'}</strong><small>${used} de ${group.capacityTotal} ${group.capacityUnit} usadas na obra · instalado fisicamente em ${host?.name||'local não informado'}</small><span>${group.allocations.map(entry=>`${(state.data.quoteRooms||[]).find(room=>room.id===entry.roomId)?.name||'Ambiente'}: ${entry.amount}`).join(' · ')}</span></article>`}).join('')}</div></section>`:'';return capacityDistributionView().replace(/(<button class="link-button" data-move-quote-item="([^":]+):(\d+)">Mover<\/button>)/g,(match,button,roomId,index)=>{const item=(state.data.quoteRooms||[]).find(room=>room.id===roomId)?.items?.[Number(index)],distributed=Boolean(item?.capacityAllocation);return `${distributed?'':button}<button class="link-button" data-distribute-capacity="${roomId}:${index}">Distribuir</button>`}).replace('<div class="room-grid">',summary+'<div class="room-grid">')};
