const compactQuoteRoomView=views.quoteDetail;views.quoteDetail=()=>compactQuoteRoomView().replace('<th>Item</th><th>Ações</th><th>Qtd.</th><th>Desconto</th><th>Venda</th><th>Total</th><th></th>','<th>Item</th><th>Ações</th><th>Qtd.</th><th>Venda</th><th>Total</th>').replace(/(<td>[^<]*<\/td>)<td>\d+(?:[.,]\d+)?%<\/td>(<td>R\$)/g,'$1$2');
