// Leitura para cliente/arquiteto: módulos centrais de iluminação aparecem pelo que atendem, não apenas pelo cômodo onde estão instalados.
function isLightingCircuitGroup(group){
  const product=productById(group.productId),description=`${product?.name||''} ${product?.model||''} ${group.capacityUnit||''}`;
  return /circuit/i.test(group.capacityUnit||'')&&/(ilumin|lumin|dimmer|pwm|rel[eé]|lighting)/i.test(description);
}
function lightingCircuitsForRoom(quoteId,roomId){
  return capacityGroups(quoteId).filter(isLightingCircuitGroup).reduce((total,group)=>total+Number(group.allocations.find(item=>item.roomId===roomId)?.amount||0),0);
}
const lightingCircuitQuoteView=views.quoteDetail;
views.quoteDetail=()=>{
  const quote=state.data.quotes.find(item=>item.id===state.selectedQuote);
  if(!quote)return lightingCircuitQuoteView();
  const rooms=(state.data.quoteRooms||[]).filter(room=>room.quoteId===quote.id),groups=capacityGroups(quote.id).filter(isLightingCircuitGroup);
  if(!groups.length)return lightingCircuitQuoteView();
  const total=groups.reduce((sum,group)=>sum+Number(group.capacityTotal||0),0);
  const panel=`<section class="card lighting-circuits-summary"><div class="card-head"><div><h3>Circuitos de iluminação por ambiente</h3><p class="subtext">${total} circuitos previstos nos módulos de iluminação. A quantidade mostra o que cada ambiente utiliza, mesmo que o módulo esteja instalado em outro local.</p></div></div><div class="lighting-circuit-grid">${rooms.map(room=>{const circuits=lightingCircuitsForRoom(quote.id,room.id);return `<article><strong>${room.name}</strong><b>${circuits}</b><span>${circuits===1?'circuito de iluminação':'circuitos de iluminação'}</span></article>`}).join('')}</div></section>`;
  return lightingCircuitQuoteView().replace('<div class="room-grid">',panel+'<div class="room-grid">');
};
const lightingCircuitRender=render;
render=()=>{
  lightingCircuitRender();
  if(state.view!=='quoteDetail')return;
  const quote=state.data.quotes.find(item=>item.id===state.selectedQuote);
  if(!quote)return;
  const hasLightingCircuits=capacityGroups(quote.id).some(isLightingCircuitGroup);
  if(hasLightingCircuits){
  document.querySelectorAll('.room-grid .room-card').forEach(card=>{
    const room=(state.data.quoteRooms||[]).find(item=>item.quoteId===quote.id&&item.name===card.querySelector('.card-head h3')?.textContent);
    const target=card.querySelector('.card-head small');
    if(!room||!target||target.querySelector('.lighting-circuit-inline'))return;
    const circuits=lightingCircuitsForRoom(quote.id,room.id),label=circuits===1?'circuito':'circuitos';
    target.insertAdjacentHTML('beforeend',` <span class="lighting-circuit-inline">· 💡 ${circuits} ${label}</span>`);
  });
  document.querySelectorAll('.room-grid .room-card').forEach(card=>{
    const room=(state.data.quoteRooms||[]).find(item=>item.quoteId===quote.id&&item.name===card.querySelector('.card-head h3')?.textContent);
    if(!room)return;
    const visibleItems=(room.items||[]).filter(item=>productById(item.productId));
    card.querySelectorAll('tbody tr').forEach((row,index)=>{
      const item=visibleItems[index],allocation=item?.capacityAllocation;
      if(!allocation||!isLightingCircuitGroup({...allocation,productId:item.productId}))return;
      const quantityCell=row.children[2]; // Ações ocupa a segunda coluna no orçamento compacto.
      if(!quantityCell||quantityCell.querySelector('.circuit-allocation'))return;
      const circuits=Number(allocation.amount||0),label=circuits===1?'circuito':'circuitos';
      quantityCell.insertAdjacentHTML('beforeend',`<small class="circuit-allocation">💡 ${circuits} ${label}</small>`);
    });
  });
  }
  document.querySelectorAll('.room-grid .room-card').forEach(card=>{
    const room=(state.data.quoteRooms||[]).find(item=>item.quoteId===quote.id&&item.name===card.querySelector('.card-head h3')?.textContent);
    if(!room)return;
    const visibleItems=(room.items||[]).filter(item=>productById(item.productId));
    card.querySelectorAll('tbody tr').forEach((row,index)=>{
      const item=visibleItems[index],allocation=item?.capacityAllocation;
      if(!allocation||allocation.hostRoomId===room.id||row.dataset.rateioSecondary)return;
      const host=(state.data.quoteRooms||[]).find(entry=>entry.id===allocation.hostRoomId);
      row.dataset.rateioSecondary='true';row.classList.add('rateio-secondary');
      const detail=row.querySelector('td .subtext');
      detail?.insertAdjacentHTML('beforeend',` <span class="rateio-secondary-note">· Rateio técnico · módulo em ${host?.name||'outro ambiente'}</span>`);
    });
  });
  document.querySelectorAll('.room-grid .room-card').forEach(card=>{
    const room=(state.data.quoteRooms||[]).find(item=>item.quoteId===quote.id&&item.name===card.querySelector('.card-head h3')?.textContent);
    if(!room)return;
    const visibleItems=(room.items||[]).filter(item=>productById(item.productId));
    card.querySelectorAll('tbody tr').forEach((row,index)=>{
      const item=visibleItems[index],actionCell=row.querySelector('[data-edit-quote-item]')?.closest('td');
      if(!item||!actionCell||actionCell.querySelector('[data-delete-quote-item]'))return;
      actionCell.insertAdjacentHTML('beforeend',` <button class="link-button quote-item-replace" data-replace-quote-item="${room.id}:${index}">Substituir</button> <button class="link-button quote-item-delete" data-delete-quote-item="${room.id}:${index}">Excluir</button>`);
    });
  });
};
render();

function deleteQuoteItem(roomId,itemIndex){
  const room=(state.data.quoteRooms||[]).find(item=>item.id===roomId),item=room?.items?.[Number(itemIndex)],product=item&&productById(item.productId);
  if(!room||!item||!product)return;
  const groupId=item.capacityAllocation?.groupId,distributed=Boolean(groupId),message=distributed
    ?`Excluir “${product.name}” do orçamento?\n\nEle é um item rateado. A exclusão remove todas as frações deste item nos ambientes atendidos.`
    :`Excluir “${product.name}” do ambiente ${room.name}?`;
  if(!confirm(message))return;
  const before=structuredClone(state.data);
  if(distributed)(state.data.quoteRooms||[]).filter(entry=>entry.quoteId===room.quoteId).forEach(entry=>entry.items=(entry.items||[]).filter(entryItem=>entryItem.capacityAllocation?.groupId!==groupId));
  else room.items.splice(Number(itemIndex),1);
  logAudit('Excluiu item','Orçamento',`${product.name} · ${distributed?'item rateado removido de todos os ambientes':'removido de '+room.name}`);
  persist();render();offerUndo(`${product.name} foi excluído do orçamento.`,before);
}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-delete-quote-item]');
  if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  const [roomId,index]=button.dataset.deleteQuoteItem.split(':');
  deleteQuoteItem(roomId,Number(index));
},true);

function openQuoteItemReplace(roomId,itemIndex){
  const room=(state.data.quoteRooms||[]).find(item=>item.id===roomId),item=room?.items?.[Number(itemIndex)],current=item&&productById(item.productId);
  if(!room||!item||!current)return;
  const distributed=Boolean(item.capacityAllocation?.groupId),options=(state.data.products||[]).filter(product=>product.active!==false).map(product=>`<option value="${product.id}" ${product.id===current.id?'selected':''}>${product.name} · ${product.model||product.category||'Sem modelo'} · ${product.price?money(product.price):'A cotar'}</option>`).join('');
  $('#dialogTitle').textContent='Substituir item do orçamento';
  $('#recordForm').dataset.kind='quoteItemReplace';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Substituir e preservar vínculos';
  $('#formFields').innerHTML=`<input type="hidden" name="roomId" value="${roomId}"><input type="hidden" name="itemIndex" value="${itemIndex}"><div class="field full"><label>Item atual</label><input value="${current.name}" disabled></div><div class="field full"><label>Novo produto ou serviço *</label><select name="productId" required>${options}</select></div><div class="field full"><p class="subtext">${distributed?'Este item possui rateio técnico. A troca será aplicada em todos os ambientes atendidos e preservará local físico, conexões, circuitos e distribuição atual.':'A troca preserva quantidade, desconto e o ambiente deste item.'}</p></div>`;
  $('#recordDialog').showModal();
}
const quoteItemReplaceSave=saveRecord;
saveRecord=(kind,data,editId='')=>{
  if(kind!=='quoteItemReplace')return quoteItemReplaceSave(kind,data,editId);
  const room=(state.data.quoteRooms||[]).find(item=>item.id===data.roomId),item=room?.items?.[Number(data.itemIndex)],from=item&&productById(item.productId),to=productById(data.productId);
  if(!room||!item||!from||!to){toast('Não foi possível identificar o item para substituição.');return false}
  if(from.id===to.id){toast('Selecione um produto diferente para substituir.');return false}
  const groupId=item.capacityAllocation?.groupId,distributed=Boolean(groupId);
  if(distributed)(state.data.quoteRooms||[]).filter(entry=>entry.quoteId===room.quoteId).forEach(entry=>(entry.items||[]).forEach(entryItem=>{if(entryItem.capacityAllocation?.groupId===groupId)entryItem.productId=to.id}));
  else item.productId=to.id;
  logAudit('Substituiu item','Orçamento',`${from.name} → ${to.name}${distributed?' · rateio, capacidade e conexões preservados':''}`);
  persist();closeRecordDialog();render();toast(distributed?'Equipamento substituído em todo o rateio; conexões e distribuição foram preservadas.':'Item substituído no ambiente.');return;
};
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-replace-quote-item]');
  if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  const [roomId,index]=button.dataset.replaceQuoteItem.split(':');
  openQuoteItemReplace(roomId,Number(index));
},true);

// Portas ignoradas não são consumo técnico: são uma decisão explícita de não usar a sobra daquele equipamento neste projeto.
state.data.capacityIgnored=state.data.capacityIgnored&&typeof state.data.capacityIgnored==='object'?state.data.capacityIgnored:{};
const capacityIgnoredNormalize=normalizeSharedData;
normalizeSharedData=shared=>{const data=capacityIgnoredNormalize(shared);data.capacityIgnored=data.capacityIgnored&&typeof data.capacityIgnored==='object'?data.capacityIgnored:{};return data};
function ignoredCapacityFor(groupId,total,used){return Math.max(0,Math.min(Number(state.data.capacityIgnored?.[groupId]||0),Math.max(0,Number(total||0)-Number(used||0))))}
function technicalPointPanel(project){
  if(!project)return '';
  const points=(state.data.technicalPoints||[]).filter(point=>point.projectId===project.id),sources=projectCapacitySources(project),roomName=id=>projectQuoteRooms(project).find(room=>room.id===id)?.name||'Ambiente não informado';
  const sourceCards=sources.map(source=>{const used=points.filter(point=>point.capacityGroupId===source.groupId).reduce((sum,point)=>sum+Number(point.quantity||0),0),planned=Number(source.capacityUsed??source.capacityTotal),rawFree=Number(source.capacityTotal||0)-used,ignored=ignoredCapacityFor(source.groupId,source.capacityTotal,used),free=Math.max(0,rawFree-ignored),ignorable=Math.max(0,Number(source.capacityTotal||0)-Math.max(planned,used)),status=rawFree<0?'over':ignored>0?'ignored':free===0?'full':'ok',action=ignored>0?`<button class="link-button capacity-ignore" data-ignore-capacity="${source.groupId}">Reconsiderar ${ignored} porta(s)</button>`:ignorable>0?`<button class="link-button capacity-ignore" data-ignore-capacity="${source.groupId}">Ignorar ${ignorable} porta(s) não usadas</button>`:'';return `<article class="technical-capacity ${status}"><strong>${source.name}</strong><small>${source.hostName} · ${source.capacityTotal} ${source.capacityUnit}</small><div><span>Rateadas <b>${planned}</b></span><span>Ocupadas <b>${used}</b></span><span>Livres <b>${free}</b></span>${ignored?`<span>Ignoradas <b>${ignored}</b></span>`:''}</div><em>${rawFree<0?`Faltam ${Math.abs(rawFree)} portas`:ignored?`${ignored} porta(s) livre(s) ignorada(s) no planejamento`:used<planned?`${planned-used} porta(s) ainda aguardam ponto no diagrama`:free===0?'Capacidade completa':'Capacidade disponível'}</em>${action}</article>`}).join('')||'<p class="subtext technical-empty">Nenhum switch/central com capacidade em portas foi distribuído neste orçamento ainda.</p>';
  const pointRows=points.map(point=>{const source=sources.find(item=>item.groupId===point.capacityGroupId);return `<tr><td><strong>${point.label}</strong><div class="subtext">${point.type}${point.note?` · ${point.note}`:''}</div></td><td>${roomName(point.roomId)}</td><td>${point.quantity}</td><td>${source?source.name:'Não vinculado'}</td><td><button class="link-button" data-edit-technical-point="${point.id}">Ajustar</button> <button class="link-button technical-delete" data-delete-technical-point="${point.id}">Excluir</button></td></tr>`});
  return `<section class="card technical-points-panel"><div class="card-head"><div><h3>Portas e pontos técnicos</h3><p class="subtext">Conferência de pontos de rede, câmeras, antenas e outros consumos que alimentam o diagrama.</p></div><button class="button primary" data-add-technical-point="${project.id}">+ Adicionar ponto</button></div><div class="technical-capacity-grid">${sourceCards}</div>${table(['Ponto','Ambiente','Portas','Capacidade vinculada',''],pointRows)}</section>`;
}
function toggleIgnoredCapacity(groupId){
  const quoteIds=[...new Set((state.data.quoteRooms||[]).map(room=>room.quoteId))],group=quoteIds.flatMap(quoteId=>capacityGroups(quoteId)).find(item=>item.groupId===groupId);
  if(!group)return;
  const used=(state.data.technicalPoints||[]).filter(point=>point.capacityGroupId===groupId).reduce((sum,point)=>sum+Number(point.quantity||0),0),planned=Number(group.capacityUsed??group.capacityTotal),rawFree=Math.max(0,Number(group.capacityTotal||0)-Math.max(planned,used)),currentlyIgnored=ignoredCapacityFor(groupId,group.capacityTotal,used),product=productById(group.productId);
  if(currentlyIgnored){delete state.data.capacityIgnored[groupId];logAudit('Reconsiderou portas livres','Diagrama',`${product?.name||'Equipamento'} · ${currentlyIgnored} porta(s) voltaram para disponibilidade`);toast(`${currentlyIgnored} porta(s) voltaram para disponibilidade.`)}
  else if(rawFree){state.data.capacityIgnored[groupId]=rawFree;logAudit('Ignorou portas livres','Diagrama',`${product?.name||'Equipamento'} · ${rawFree} porta(s) não utilizadas neste projeto`);toast(`${rawFree} porta(s) foram marcadas como não utilizadas neste projeto.`)}
  else {toast('Não há portas livres para ignorar.');return}
  persist();render();
}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-ignore-capacity]');
  if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();toggleIgnoredCapacity(button.dataset.ignoreCapacity);
},true);
